40: /**
41:  * Helper class for UML metamodel.
42:  *
43:  * @since ARGO0.11.2
44:  * @author Thierry Lach
45:  * @stereotype singleton
46:  */
47: public class UmlHelper {
48: 	
49:     
50:     private static final Logger LOG = Logger.getLogger(UmlHelper.class);
51:     
52:     /** Singleton instance.
53:      */
54:     private static UmlHelper singleton =
55: 	new UmlHelper();
56: 
57: 
58:     /** Don't allow instantiation.
59:      */
60:     private UmlHelper() {
61:     }
62: 
63:     /** 
64:      *  Ensures that all of the elements in a model are registered
65:      *  to the UmlModelListener.  This is useful when the MModel is
66:      *  not created by the UmlFactory.
67:      *
68:      * @param model the UML model
69:      */
70:     public void addListenersToModel(Object model) {
71:         
72:         if (!ModelFacade.isAModel(model))
73:             throw new IllegalArgumentException();
74:         
75: 	addListenersToMBase(model);
76:     }
77: 
78:     /** 
79:      *  Internal recursive worker to add UmlModelListener.
80:      *
81:      * @param mbase the element to add listeners to
82:      */
83:     protected void addListenersToMBase(Object mbase) {     
84:         
85:         if (!ModelFacade.isABase(mbase))
86:             throw new IllegalArgumentException();
87:         
88: 	UmlFactory.getFactory().addListenersToModelElement(mbase);
89: 	Collection elements = ((MBase) mbase).getModelElementContents();
90: 	if (elements != null) {
91: 	    Iterator iterator = elements.iterator();
92: 	    while (iterator.hasNext()) {
93: 	        Object o = iterator.next();
94: 	        if (o instanceof MBase) {
95: 	            addListenersToMBase(o);
96: 	        }
97: 	    }
98: 	}
99:     }
100:     
101:     /** Singleton instance access method.
102:      *
103:      * @return the singleton
104:      */
105:     public static UmlHelper getHelper() {
106:         return singleton;
107:     }
108:     
109:     /** Returns the package helper for the UML
110:      *  package Foundation::ExtensionMechanisms.
111:      *  
112:      *  @return the ExtensionMechanisms helper instance.
113:      */
114:     public ExtensionMechanismsHelper getExtensionMechanisms() {
115:         return ExtensionMechanismsHelper.getHelper();
116:     }
117: 
118:     /** Returns the package helper for the UML
119:      *  package Foundation::DataTypes.
120:      *  
121:      *  @return the DataTypes helper instance.
122:      */
123:     public DataTypesHelper getDataTypes() {
124:         return DataTypesHelper.getHelper();
125:     }
126: 
127:     /** Returns the package helper for the UML
128:      *  package Foundation::Core.
129:      *  
130:      *  @return the Core helper instance.
131:      */
132:     public CoreHelper getCore() {
133:         return CoreHelper.getHelper();
134:     }
135: 
136:     /** Returns the package helper for the UML
137:      *  package BehavioralElements::CommonBehavior.
138:      *  
139:      *  @return the CommonBehavior helper instance.
140:      */
141:     public CommonBehaviorHelper getCommonBehavior() {
142:         return CommonBehaviorHelper.getHelper();
143:     }
144: 
145:     /** Returns the package helper for the UML
146:      *  package BehavioralElements::UseCases.
147:      *  
148:      *  @return the UseCases helper instance.
149:      */
150:     public UseCasesHelper getUseCases() {
151:         return UseCasesHelper.getHelper();
152:     }
153: 
154:     /** Returns the package helper for the UML
155:      *  package BehavioralElements::StateMachines.
156:      *  
157:      *  @return the StateMachines helper instance.
158:      */
159:     public StateMachinesHelper getStateMachines() {
160:         return StateMachinesHelper.getHelper();
161:     }
162: 
163:     /** Returns the package helper for the UML
164:      *  package BehavioralElements::Collaborations.
165:      *  
166:      *  @return the Collaborations helper instance.
167:      */
168:     public CollaborationsHelper getCollaborations() {
169:         return CollaborationsHelper.getHelper();
170:     }
171: 
172:     /** Returns the package helper for the UML
173:      *  package BehavioralElements::ActivityGraphs.
174:      *  
175:      *  @return the ActivityGraphs helper instance.
176:      */
177:     public ActivityGraphsHelper getActivityGraphs() {
178:         return ActivityGraphsHelper.getHelper();
179:     }
180: 
181:     /** Returns the package helper for the UML
182:      *  package ModelManagement.
183:      *  
184:      *  @return the ModelManagement helper instance.
185:      */
186:     public ModelManagementHelper getModelManagement() {
187:         return ModelManagementHelper.getHelper();
188:     }
189:     
190:     /**
191:      * Returns the correct helper on basis of the package of base
192:      * @param base the modelelement
193:      * @return Object the helper
194:      */
195:     public Object getHelper(Object base) {
196:     	if (base instanceof MBase) {
197: 	    String name = base.getClass().getName();
198: 	    name = name.substring(0, name.lastIndexOf('.'));
199: 	    name = name.substring(name.lastIndexOf('.') + 1, name.length());
200: 	    Method[] methods = this.getClass().getMethods();
201: 	    for (int i = 0; i < methods.length; i++) {
202: 		String methodname = methods[i].getName();
203: 		if (methodname.toLowerCase().indexOf(name) >= 0) {
204: 		    try {
205: 			return methods[i].invoke(this, new Object[] {});
206: 		    } catch (IllegalAccessException e) {
207:                         LOG.warn(e);
208: 		    } catch (InvocationTargetException e) {
209:                         LOG.warn(e);
210: 		    }
211: 		}
212: 	    }
213:     	}
214:     	return null;
215:     }
216:     
217:     /**
218:      * Returns the owner of some modelelement object. In most cases this will be
219:      * the owning namespace but in some cases it will be null (the root model)
220:      * or for instance the owning class with an attribute.
221:      * @param handle the modelelement
222:      * @return Object the owner
223:      */
224:     public Object getOwner(Object handle) {
225:         if (handle instanceof MBase) {
226:             return ((MBase) handle).getModelElementContainer();
227:         }
228:         return null;
229:     }
230:     
231:     /**
232:      * Utility method to quickly delete a collection of modelelements. This
233:      * method should only be called from within the model component. The only
234:      * reason it is public is that the other helpers/factories are in other
235:      * packages and therefore cannot see this method if it is not public.
236:      * @param col a collection of modelelements
237:      */
238:     public void deleteCollection(Collection col) {
239:         Iterator it = col.iterator();
240:         while (it.hasNext()) {
241:             UmlFactory.getFactory().delete(it.next());
242:         }        
243:     }
244:     
245:     /**
246:      * Returns the source of some relationship. 
247:      * This is the element in binary relations from which a relation 'departs'.
248:      * @param relationShip the relationship to be tested
249:      * @return the source of the relationship
250:      */
251:     public Object getSource(Object relationShip) {
252:         if (relationShip == null) {
253:             throw new IllegalArgumentException("Argument relationship is null");
254:         }
255:         if (!(ModelFacade.isAModelElement(relationShip) 
256:                 || relationShip instanceof CommentEdge)) {
257:            throw new IllegalArgumentException("Argument relationship of class " 
258:                    + relationShip.getClass().toString() 
259:                    + " is not a valid relationship"); 
260:         }     
261:         if (relationShip instanceof CommentEdge) {
262:             return ((CommentEdge) relationShip).getSource();
263:         }
264:         if (ModelFacade.isARelationship(relationShip)) { 
265:             // handles all children of relationship including extend and 
266:             // include which are not members of core 
267:             return CoreHelper.getHelper().getSource(relationShip);
268:         }
269:         if (ModelFacade.isATransition(relationShip)) {
270:             return StateMachinesHelper.getHelper().getSource(relationShip);
271:         }
272:         return null;
273:     }
274:     
275:     /**
276:      * Returns the destination of some relationship. 
277:      * This is the element in binary relations at which a relation 'arrives'.
278:      * @param relationShip  the relationship to be tested
279:      * @return the destination of the relationship
280:      */
281:     public Object getDestination(Object relationShip) {
282:         if (relationShip == null) {
283:             throw new IllegalArgumentException("Argument relationship is null");
284:         }
285:         if (!(ModelFacade.isAModelElement(relationShip) 
286:                 || relationShip instanceof CommentEdge)) {
287:            throw new IllegalArgumentException("Argument relationship of class " 
288:                    + relationShip.getClass().toString() 
289:                    + " is not a valid relationship"); 
290:         }     
291:         if (relationShip instanceof CommentEdge) {
292:             return ((CommentEdge) relationShip).getDestination();
293:         }
294:         if (ModelFacade.isARelationship(relationShip)) { 
295:             // handles all children of relationship including extend and 
296:             // include which are not members of core 
297:             return CoreHelper.getHelper().getDestination(relationShip);
298:         }
299:         if (ModelFacade.isATransition(relationShip)) {
300:             return StateMachinesHelper.getHelper().getDestination(relationShip);
301:         }
302:         return null;
303:     }
304:     
305: }
