63:     /** 
64:      *  Ensures that all of the elements in a model are registered
65:      *  to the UmlModelListener.  This is useful when the MModel is
66:      *  not created by the UmlFactory.
67:      *
68:      * @param model the UML model
69:      */
70:     public void addListenersToModel(Object model) {
71:         
72:         if (!ModelFacade.isAModel(model))
73:             throw new IllegalArgumentException();
74:         
75: 	addListenersToMBase(model);
76:     }
77: 
78:     /** 
79:      *  Internal recursive worker to add UmlModelListener.
80:      *
81:      * @param mbase the element to add listeners to
82:      */
83:     protected void addListenersToMBase(Object mbase) {     
84:         
85:         if (!ModelFacade.isABase(mbase))
86:             throw new IllegalArgumentException();
87:         
88: 	UmlFactory.getFactory().addListenersToModelElement(mbase);
89: 	Collection elements = ((MBase) mbase).getModelElementContents();
90: 	if (elements != null) {
91: 	    Iterator iterator = elements.iterator();
92: 	    while (iterator.hasNext()) {
93: 	        Object o = iterator.next();
94: 	        if (o instanceof MBase) {
95: 	            addListenersToMBase(o);
96: 	        }
97: 	    }
98: 	}
99:     }
