46: /**
47:  * Class to display graphics for a UML ActionState in a diagram.
48:  * It contains a multiline textfield for the Entry Action Expression.
49:  *
50:  * @author ics 125b silverbullet team
51:  */
52: public class FigActionState extends FigStateVertex {
53: 
54:     ////////////////////////////////////////////////////////////////
55:     // constants
56: 
57:     private static final int PADDING = 8;
58: 
59:     ////////////////////////////////////////////////////////////////
60:     // instance variables
61: 
62:     private FigRRect cover;
63: 
64:     /**
65:      * The notation provider for the textfield.
66:      */
67:     protected NotationProvider notationProvider;
68: 
69:     ////////////////////////////////////////////////////////////////
70:     // constructors
71: 
72:     /**
73:      * Constructor FigActionState.
74:      */
75:     public FigActionState() {
76:         setBigPort(new FigRRect(10 + 1, 10 + 1, 90 - 2, 25 - 2, Color.cyan,
77:                 Color.cyan));
78:         ((FigRRect) getBigPort()).setCornerRadius(getBigPort().getHeight() / 2);
79:         cover = new FigRRect(10, 10, 90, 25, Color.black, Color.white);
80:         cover.setCornerRadius(getHeight() / 2);
81: 
82:         // overrule the single-line namefig created by the parent
83:         setNameFig(new FigMultiLineText(10 + PADDING, 10, 90 - PADDING * 2, 25,
84:                 true));
85:         getNameFig().setText(placeString());
86:         getNameFig().setBotMargin(7); // make space for the clarifier
87:         getNameFig().setTopMargin(7); // for vertical symmetry
88:         getNameFig().setRightMargin(4); // margin between text and border
89:         getNameFig().setLeftMargin(4);
90:         getNameFig().setJustification(FigText.JUSTIFY_CENTER);
91: 
92:         getBigPort().setLineWidth(0);
93: 
94:         // add Figs to the FigNode in back-to-front order
95:         addFig(getBigPort());
96:         addFig(cover);
97:         addFig(getStereotypeFig());
98:         addFig(getNameFig());
99: 
100:         //setBlinkPorts(false); //make port invisble unless mouse enters
101:         Rectangle r = getBounds();
102:         setBounds(r.x, r.y, r.width, r.height);
103:     }
104: 
105:     /**
106:      * Constructor FigActionState.
107:      *
108:      * @param gm ignored!
109:      * @param node owner
110:      */
111:     public FigActionState(GraphModel gm, Object node) {
112:         this();
113:         setOwner(node);
114:     }
115: 
116:     /*
117:      * @see org.argouml.uml.diagram.state.ui.FigStateVertex#initNotationProviders(java.lang.Object)
118:      */
119:     protected void initNotationProviders(Object own) {
120:         super.initNotationProviders(own);
121:         if (Model.getFacade().isAActionState(own)) {
122:             notationProvider =
123:                 NotationProviderFactory2.getInstance().getNotationProvider(
124:                     NotationProviderFactory2.TYPE_ACTIONSTATE, own);
125:         }
126:     }
127: 
128:     /*
129:      * @see java.lang.Object#clone()
130:      */
131:     public Object clone() {
132:         FigActionState figClone = (FigActionState) super.clone();
133:         Iterator it = figClone.getFigs().iterator();
134:         figClone.setBigPort((FigRRect) it.next());
135:         figClone.cover = (FigRRect) it.next();
136:         figClone.setNameFig((FigText) it.next());
137:         /* TODO: Do we need to clone the stereotype(s)? */
138:         return figClone;
139:     }
140: 
141:     /*
142:      * @see org.tigris.gef.presentation.Fig#getMinimumSize()
143:      */
144:     public Dimension getMinimumSize() {
145:         Dimension stereoDim = getStereotypeFig().getMinimumSize();
146:         Dimension nameDim = getNameFig().getMinimumSize();
147: 
148:         int w = Math.max(stereoDim.width, nameDim.width) + PADDING * 2;
149:         /* The stereoDim has height=2, even if it is empty, 
150:          * hence the -2 below: */
151:         int h = stereoDim.height - 2 + nameDim.height + PADDING;
152:         w = Math.max(w, h + 44); // the width needs to be > the height
153:         return new Dimension(w, h);
154:     }
155: 
156:     /*
157:      * @see org.tigris.gef.presentation.Fig#setBoundsImpl(int, int, int, int)
158:      *
159:      * Override setBounds to keep shapes looking right.
160:      */
161:     protected void setBoundsImpl(int x, int y, int w, int h) {
162:         if (getNameFig() == null) {
163:             return;
164:         }
165:         Rectangle oldBounds = getBounds();
166: 
167:         Dimension stereoDim = getStereotypeFig().getMinimumSize();
168:         Dimension nameDim = getNameFig().getMinimumSize();
169:         getNameFig().setBounds(x + PADDING, y + stereoDim.height,
170:                 w - PADDING * 2, nameDim.height);
171:         getStereotypeFig().setBounds(x + PADDING, y,
172:                 w - PADDING * 2, stereoDim.height);
173:         getBigPort().setBounds(x + 1, y + 1, w - 2, h - 2);
174:         cover.setBounds(x, y, w, h);
175:         ((FigRRect) getBigPort()).setCornerRadius(h);
176:         cover.setCornerRadius(h);
177: 
178:         calcBounds();
179:         updateEdges();
180:         firePropChange("bounds", oldBounds, getBounds());
181:     }
182: 
183:     /*
184:      * @see org.tigris.gef.presentation.Fig#setLineColor(java.awt.Color)
185:      */
186:     public void setLineColor(Color col) {
187:         cover.setLineColor(col);
188:     }
189: 
190:     /*
191:      * @see org.tigris.gef.presentation.Fig#getLineColor()
192:      */
193:     public Color getLineColor() {
194:         return cover.getLineColor();
195:     }
196: 
197:     /*
198:      * @see org.tigris.gef.presentation.Fig#setFillColor(java.awt.Color)
199:      */
200:     public void setFillColor(Color col) {
201:         cover.setFillColor(col);
202:     }
203: 
204:     /*
205:      * @see org.tigris.gef.presentation.Fig#getFillColor()
206:      */
207:     public Color getFillColor() {
208:         return cover.getFillColor();
209:     }
210: 
211:     /*
212:      * @see org.tigris.gef.presentation.Fig#setFilled(boolean)
213:      */
214:     public void setFilled(boolean f) {
215:         cover.setFilled(f);
216:     }
217: 
218:     /*
219:      * @see org.tigris.gef.presentation.Fig#getFilled()
220:      */
221:     public boolean getFilled() {
222:         return cover.getFilled();
223:     }
224: 
225:     /*
226:      * @see org.tigris.gef.presentation.Fig#setLineWidth(int)
227:      */
228:     public void setLineWidth(int w) {
229:         cover.setLineWidth(w);
230:     }
231: 
232:     /*
233:      * @see org.tigris.gef.presentation.Fig#getLineWidth()
234:      */
235:     public int getLineWidth() {
236:         return cover.getLineWidth();
237:     }
238: 
239:     /*
240:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
241:      */
242:     protected void modelChanged(PropertyChangeEvent mee) {
243:         super.modelChanged(mee);
244:         if (mee instanceof AddAssociationEvent
245:                 || mee instanceof AttributeChangeEvent) {
246:             renderingChanged();
247:             initialiseListener(getOwner(), getOwner());
248:             damage();
249:         }
250:     }
251:     
252:     /*
253:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateListeners(java.lang.Object)
254:      */
255:     protected void initialiseListener(Object oldOwner, Object newOwner) {
256:         if (oldOwner != null) {
257:             removeAllElementListeners();
258:         }
259:         /* Now, let's register for events from all modelelements
260:          * that change the body text: 
261:          */
262:         if (newOwner != null) {
263:             addElementListener(newOwner, 
264:                     new String[] {"entry", "remove", "stereotype"} );
265:             Object entry = Model.getFacade().getEntry(newOwner);
266:             if (entry != null) {
267:                 addElementListener(entry, "script");
268:             }
269:             Collection c = Model.getFacade().getStereotypes(newOwner);
270:             Iterator i = c.iterator();
271:             while (i.hasNext()) {
272:                 Object st = i.next();
273:                 addElementListener(st, "name");
274:             }
275:         }
276:     }
277: 
278: 
279:     /*
280:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
281:      */
282:     protected void updateNameText() {
283:         if (notationProvider != null) {
284:             getNameFig().setText(notationProvider.toString(getOwner(), null));
285:         }
286:     }
287: 
288:     /*
289:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
290:      */
291:     protected void updateStereotypeText() {
292:         getStereotypeFig().setOwner(getOwner());
293:     }
294: 
295:     /*
296:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEdited(org.tigris.gef.presentation.FigText)
297:      */
298:     protected void textEdited(FigText ft) throws PropertyVetoException {
299:         notationProvider.parse(getOwner(), ft.getText());
300:         ft.setText(notationProvider.toString(getOwner(), null));
301:     }
302: 
303:     /*
304:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEditStarted(org.tigris.gef.presentation.FigText)
305:      */
306:     protected void textEditStarted(FigText ft) {
307:         if (ft == getNameFig()) {
308:             showHelp(notationProvider.getParsingHelp());
309:         }
310:     }
311: 
312:     /**
313:      * The UID.
314:      */
315:     private static final long serialVersionUID = -3526461404860044420L;
316: } /* end class FigActionState */
