425:                 ParserDisplay.SINGLETON.parseObjectFlowState1(ft.getText(),
426:                     this.getOwner());
427:             } else if (ft == state && this.getOwner() != null) {
428:                 ParserDisplay.SINGLETON.parseObjectFlowState2(ft.getText(),
429:                         this.getOwner());
430:             }
431:             ProjectBrowser.getInstance().getStatusBar().showStatus("");
432:         } catch (ParseException pe) {
433:             String msg = "statusmsg.bar.error.parsing.objectflowstate";
434:             Object[] args = {
435:                 pe.getLocalizedMessage(),
436:                 new Integer(pe.getErrorOffset()),
437:             };
438:             ProjectBrowser.getInstance().getStatusBar().showStatus(
439:                     Translator.messageFormat(msg, args));
440:             updateClassifierText();
441:             updateStateText();
442:         }
443:     }
444: 
445:     /**
446:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEditStarted(org.tigris.gef.presentation.FigText)
447:      */
448:     protected void textEditStarted(FigText ft) {
449:         if (ft == getNameFig()) {
450:             showHelp("parsing.help.fig-objectflowstate1");
451:         }
452:         if (ft == state) {
453:             showHelp("parsing.help.fig-objectflowstate2");
454:         }
455:     }
456: 
457: } /* end class FigObjectFlowState */
