99:     private FigPoly urCorner; // the upper right corner
100:     
101:     /**
102:      * Flag to indicate that we have just been created. This is to fix the
103:      * problem with loading comments that have stereotypes already
104:      * defined.<p>
105:      */
106:     private boolean newlyCreated = false;
