111:     /**
112:      * The main constructor used for file loading.
113:      */
114:     public FigComment() {
115: 
116:         body = new FigPoly(Color.black, Color.white);
117:         body.addPoint(x, y);
118:         body.addPoint(x + width - 1 - dogear, y);
119:         body.addPoint(x + width - 1, y + dogear);
120:         body.addPoint(x + width - 1, y + height - 1);
121:         body.addPoint(x, y + height - 1);
122:         body.addPoint(x, y);
123:         body.setFilled(true);
124:         body.setLineWidth(1);
125: 
126:         urCorner = new FigPoly(Color.black, Color.white);
127:         urCorner.addPoint(x + width - 1 - dogear, y);
128:         urCorner.addPoint(x + width - 1, y + dogear);
129:         urCorner.addPoint(x + width - 1 - dogear, y + dogear);
130:         urCorner.addPoint(x + width - 1 - dogear, y);
131:         urCorner.setFilled(true);
132:         Color col = body.getFillColor();
133:         urCorner.setFillColor(col.darker());
134:         urCorner.setLineWidth(1);
135: 
136:         if (SingleStereotypeEnabler.isEnabled()) {
137:             getStereotypeFig().setHeight(STEREOHEIGHT);
138:             getStereotypeFig().setVisible(false);
139:         }
140:         
141:         setBigPort(new FigRect(x, y, width, height, null, null));
142:         getBigPort().setFilled(false);
143:         getBigPort().setLineWidth(0);
144: 
145:         nameText = new FigMultiLineText(x + 2, y + 2, width - 2 - dogear,
146:                 (height - 4) / 2, true);
147: 
148:         seperator = new FigLine();
149:         seperator.setDashed(true);
150:         
151:         bodyText = new FigMultiLineText(x + 2, y + 2, width - 2 - dogear,
152:                 (height - 4) / 2, true);
153: 
154: 
155:         // add Figs to the FigNode in back-to-front order
156:         addFig(getBigPort());
157:         addFig(body);
158:         addFig(urCorner);
159:         addFig(getStereotypeFig());
160:         addFig(nameText);
161:         addFig(seperator);
162:         addFig(bodyText);
163:         
164:         setBlinkPorts(false); //make port invisble unless mouse enters
165:         Rectangle r = getBounds();
166:         setBounds(r.x, r.y, r.width, r.height);
167:         updateEdges();
168: 
169:         readyToEdit = false;
170:         // Mark this as newly created. This is to get round the problem with
171:         // creating figs for loaded comments that had stereotypes. They are
172:         // saved with their dimensions INCLUDING the stereotype, but since we
173:         // pretend the stereotype is not visible, we add height the first time
174:         // we render such a comment. This is a complete fudge, and really we
175:         // ought to address how comment objects with stereotypes are saved. But
176:         // that will be hard work.
177:         newlyCreated = true;
178:     }
