239:      * down to one of the internal Figs.  This allows the user to
240:      * initiate direct text editing.
241:      *
242:      * @see java.awt.event.MouseListener#mouseClicked(java.awt.event.MouseEvent)
243:      */
244:     public void mouseClicked(MouseEvent me) {
245:         if (!readyToEdit) {
246:             if (Model.getFacade().isAModelElement(getOwner())) {
247:                 readyToEdit = true;
248:             } else {
249:                 LOG.debug("not ready to edit note");
250:                 return;
251:             }
252:         }
253:         if (me.isConsumed()) {
254:             return;
255:         }
256:         if (me.getClickCount() >= 2
257: 	    && !(me.isPopupTrigger()
258: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
259:             if (getOwner() == null) {
260:                 return;
261:             }
262:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
263:             if (f instanceof MouseListener) {
264:                 ((MouseListener) f).mouseClicked(me);
265:             }
266:         }
267:         me.consume();
268:     }
