519:     public Dimension getMinimumSize() {
520: 
521:         // Get the size of the name text field.
522:         Dimension aSize = nameText.getMinimumSize();
523:         
524:         // Add size of the body text field & separator height
525:         Dimension bSize = bodyText.getMinimumSize();
526:         aSize.width = Math.max(aSize.width, bSize.width);
527:         aSize.height += bSize.height + 5;
528:             
529:         // If we have a stereotype displayed, then allow some space for that
530:         // (width and height)
531: 
532:         if (getStereotypeFig().isVisible()) {
533:             Dimension stereoMin = getStereotypeFig().getMinimumSize();
534:             aSize.width =
535:                 Math.max(aSize.width,
536:                          stereoMin.width);
537:             if (SingleStereotypeEnabler.isEnabled()) {
538:                 aSize.height += STEREOHEIGHT;
539:             } else {
540:                 aSize.height += stereoMin.height;
541:             }
542:         }
543:         
544:         // And add the gaps around the textfield to get the minimum
545:         // size of the note.
546:         return new Dimension(aSize.width + 4 + dogear,
547: 			     aSize.height + 4);
548:     }
