550:     /**
551:      * @see org.tigris.gef.presentation.Fig#setBoundsImpl(int, int, int, int)
552:      */
553:     protected void setBoundsImpl(int px, int py, int w, int h) {
554:         if (nameText == null && bodyText == null) {
555:             return;
556:         }
557:         
558:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
559:         
560:         int stereotypeHeight = 0;
561:         if (getStereotypeFig().isVisible()) {
562:             if (SingleStereotypeEnabler.isEnabled()) {
563:                 stereotypeHeight = STEREOHEIGHT;
564:             } else {
565:                 stereotypeHeight = stereoMin.height;
566:             }
567:         }
568:         
569:         Rectangle oldBounds = getBounds();
570: 
571:         // Resize the name text figure
572:         Dimension nameTextMin = nameText.getMinimumSize();
573:         int textFigHeight = nameTextMin.height;
574:         if (nameText != null) {
575:             nameText.setBounds(px + 2, py + 2 + stereotypeHeight, 
576:                     w - 4 - dogear, textFigHeight);
577:         }
578: 
579:         seperator.setX1(px);
580:         seperator.setX2(px + w);
581:         seperator.setY1(py + 2 + stereotypeHeight + textFigHeight + 3);
582:         seperator.setY2(py + 2 + stereotypeHeight + textFigHeight + 3);
583:         
584:         // Resize the body text figure
585:         if (bodyText != null) {
586:             bodyText.setBounds(px + 2, seperator.getY1() + 3, w - 4 - dogear,
587:                     bodyText.getMinimumSize().height + 2);
588:         }
589:         
590:         if (SingleStereotypeEnabler.isEnabled()) {
591:             getStereotypeFig().setBounds(px + 2, py + 2,
592:                     w - 4 - dogear, STEREOHEIGHT);
593:         } else {
594:             getStereotypeFig().setBounds(px + 2, py + 2,
595:                     w - 4 - dogear, stereoMin.height);
596:         }
597:         
598:         // Resize the big port around the figure
599:         getBigPort().setBounds(px, py, w, h);
600: 
601:         // Since this is a complex polygon, there's no easy way to resize it.
602:         Polygon newPoly = new Polygon();
603:         newPoly.addPoint(px, py);
604:         newPoly.addPoint(px + w - 1 - dogear, py);
605:         newPoly.addPoint(px + w - 1, py + dogear);
606:         newPoly.addPoint(px + w - 1, py + h - 1);
607:         newPoly.addPoint(px, py + h - 1);
608:         newPoly.addPoint(px, py);
609:         body.setPolygon(newPoly);
610: 
611:         // Just move the corner to it's new position.
612:         urCorner.setBounds(px + w - 1 - dogear, py, dogear, dogear);
613: 
614:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
615:         firePropChange("bounds", oldBounds, getBounds());
616:     }
