673:     /**
674:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
675:      */
676:     protected void updateStereotypeText() {
677:         if (SingleStereotypeEnabler.isEnabled()) {
678:             updateStereotypeTextSingleStereotype();
679:             return;
680:         }
681:         Object me = /*(MModelElement)*/ getOwner();
682: 
683:         if (me == null) {
684:             return;
685:         }
686: 
687:         Rectangle rect = getBounds();
688: 
689:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
690:         
691:         if (Model.getFacade().getStereotypes(me).isEmpty()) {
692: 
693:             if (getStereotypeFig().isVisible()) {
694:                 getStereotypeFig().setVisible(false);
695:                 rect.y += stereoMin.height;
696:                 rect.height -= stereoMin.height;
697:                 setBounds(rect.x, rect.y, rect.width, rect.height);
698:                 calcBounds();
699:             }
700:         } else {
701:             getStereotypeFig().setOwner(getOwner());
702: 
703:             if (!getStereotypeFig().isVisible()) {
704:                 getStereotypeFig().setVisible(true);
705: 
706:                 // Only adjust the stereotype height if we are not newly
707:                 // created. This gets round the problem of loading classes with
708:                 // stereotypes defined, which have the height already including
709:                 // the stereotype.
710: 
711:                 if (!newlyCreated) {
712:                     rect.y -= stereoMin.height;
713:                     rect.height += stereoMin.height;
714:                     rect.width = 
715:                         Math.max(getMinimumSize().width, rect.width);
716:                     setBounds(rect.x, rect.y, rect.width, rect.height);
717:                     calcBounds();
718:                 }
719:             }
720:         }
721:         // Whatever happened we are no longer newly created, so clear the
722:         // flag. Then set the bounds for the rectangle we have defined.
723:         newlyCreated = false;
724:     }
725:     
726:     protected void updateStereotypeTextSingleStereotype() {
727:         Object me = /*(MModelElement)*/ getOwner();
728: 
729:         if (me == null) {
730:             return;
731:         }
732: 
733:         Rectangle rect = getBounds();
734:         Object stereo = CollectionUtil.getFirstItemOrNull(
735:                 Model.getFacade().getStereotypes(me));
736: 
737:         if ((stereo == null)
738:                 || (Model.getFacade().getName(stereo) == null)
739:                 || (Model.getFacade().getName(stereo).length() == 0))   {
740: 
741:             if (getStereotypeFig().isVisible()) {
742:                 getStereotypeFig().setVisible(false);
743:                 rect.y += STEREOHEIGHT;
744:                 rect.height -= STEREOHEIGHT;
745:                 setBounds(rect.x, rect.y, rect.width, rect.height);
746:                 calcBounds();
747:             }
748:         } else {
749:             getStereotypeFig().setOwner(getOwner());
750: 
751:             if (!getStereotypeFig().isVisible()) {
752:                 getStereotypeFig().setVisible(true);
753: 
754:                 // Only adjust the stereotype height if we are not newly
755:                 // created. This gets round the problem of loading classes with
756:                 // stereotypes defined, which have the height already including
757:                 // the stereotype.
758: 
759:                 if (!newlyCreated) {
760:                     rect.y -= STEREOHEIGHT;
761:                     rect.height += STEREOHEIGHT;
762:                     rect.width = 
763:                         Math.max(getMinimumSize().width, rect.width);
764:                     setBounds(rect.x, rect.y, rect.width, rect.height);
765:                     calcBounds();
766:                 }
767:             }
768:         }
769:         // Whatever happened we are no longer newly created, so clear the
770:         // flag. Then set the bounds for the rectangle we have defined.
771:         newlyCreated = false;
772:     }
