390:     public void addModelEventListener(
391: 				      Object listener,
392: 				      Object modelelement,
393: 				      String[] eventNames) {
394:         // we just return if the modelelement is not a base. 
395:         // we don't support non-nsuml elements yet.
396:         if (modelelement == null || !ModelFacade.isABase(modelelement)) {
397:             return;
398:         }
399:         if (listener == null
400:             || eventNames == null
401:             || eventNames.length == 0
402:             || !(listener instanceof MElementListener)
403:             || !(modelelement instanceof MBase)) {
404:             throw new IllegalArgumentException("Wrong argument types while "
405: 					       + "adding a modelelement "
406: 					       + "listener");
407:         }
408:         for (int i = 0; i < eventNames.length; i++) {
409:             EventKey[] keys =
410:                 definition.getEventTypes(
411: 					  modelelement.getClass(),
412: 					  eventNames[i]);
413:             for (int j = 0; j < keys.length; j++) {
414:                 listenerMap.remove(
415: 				    (MBase) modelelement,
416: 				    keys[j],
417: 				    (MElementListener) listener);
418:                 listenerMap.put(
419: 				 (MBase) modelelement,
420: 				 keys[j],
421: 				 (MElementListener) listener);
422:             }
423:         }
424:     }
