930: /**
931:  * A wrapped object array that contains triples of eventtype,
932:  * eventname, interested listener. I used an Object array for this
933:  * purpose since it performs fast. Copied a lot of the code from
934:  * javax.swing.EventListenerList.
935:  * @author jaap.branderhorst@xs4all.nl
936:  */
937: class EventListenerList {
938:     /**
939:      * A null array to be shared by all empty listener lists.
940:      */
941:     private static final Object[] NULL_ARRAY = new Object[0];
942:     /**
943:      *  The list of EventKey - Listener pairs. It's visibility is default since
944:      * it's used in AbstractUmlModelFactory in a performant but quite awkward
945:      * way from an encapsulation point of view. 
946:      */
947:     private Object[] listenerList = NULL_ARRAY;
948: 
949:     /**
950:      * Returns an array of listeners that are interested in an event
951:      * that is typed by the given EventKey. If the name is null of the
952:      * EventKey, all listeners are returned that have the
953:      * corresponding name filled or null. Same is true for the type.
954:      *
955:      * @param key
956:      * @return An array of listeners that are interested in the event typed by
957:      * the given EventKey
958:      */
959:     public synchronized MElementListener[] getListeners(EventKey key) {
960:         Object[] lList = listenerList;
961:         int n = getListenerCount(lList, key);
962:         MElementListener[] result =
963:             (MElementListener[]) Array.newInstance(MElementListener.class, n);
964:         int j = 0;
965:         // if the event name is not set we should return all listeners
966:         // interested
967:         if (key.getType().intValue() == 0) {
968:             Integer type = key.getType();
969:             for (int i = lList.length - 3; i >= 0; i -= 3) {
970:                 if (type.equals(lList[i])) {
971:                     result[j++] = (MElementListener) lList[i + 2];
972:                 }
973:             }
974:         } else if (key.getName() != null && key.getType() != null) {
975:             Integer type = key.getType();
976:             String name = key.getName();
977:             for (int i = lList.length - 3; i >= 0; i -= 3) {
978:                 if (name.equals(lList[i + 1]) && type.equals(lList[i])) {
979:                     result[j++] = (MElementListener) lList[i + 2];
980:                 }
981:             }
982:         } else {
983:             throw new IllegalArgumentException("Illegal eventkey!");
984:         }
985:         return result;
986:     }
987: 
988:     /**
989:      * Registers the given listeners for the event typed by
990:      * EventKey. If the name is null (of the EventKey), the listener
991:      * is registred for all events that have a type corresponding to
992:      * the type in the given key, no matter what the name of the event
993:      * is. Vice versa for the type.<p>
994:      *
995:      * <strong>A listener that has been added twice will get the
996:      * events for which it registred twice. Be careful with
997:      * registring listeners!</strong>
998:      *
999:      * @param key
1000:      * @param listener
1001:      */
1002:     public synchronized void add(EventKey key, MElementListener listener) {
1003:         if (listener == null || key == null) {
1004:             throw new IllegalArgumentException("Null key or null listener");
1005:         }
1006:         // check if there allready is a listener
1007:         // if (!Arrays.asList(getListeners(key)).contains(listener)) {
1008: 
1009:         if (listenerList == NULL_ARRAY) {
1010:             // if this is the first listener added, 
1011:             // initialize the lists
1012:             listenerList =
1013:                 new Object[] {
1014: 		    key.getType(), key.getName(), listener,
1015: 		};
1016:         } else {
1017:             if (!contains(key, listener)) {
1018:                 // Otherwise copy the array and add the new listener
1019:                 int i = listenerList.length;
1020:                 Object[] tmp = new Object[i + 3];
1021:                 System.arraycopy(listenerList, 0, tmp, 0, i);
1022:                 
1023:                 tmp[i] = key.getType();
1024:                 tmp[i + 1] = key.getName();
1025:                 tmp[i + 2] = listener;            
1026:                 
1027:                 listenerList = tmp;
1028:             }
1029:         }
1030:     }
1031:     
1032:     public boolean contains(EventKey key, MElementListener listener) {       
1033:         if (key == null) {
1034:             System.out.println(" KEy null");
1035:         }
1036:         for (int i = listenerList.length - 1; i > 0; i -= 3) {
1037:             if (listenerList[i] == listener 
1038:                 && ((listenerList[i - 1] == null && key.getName() == null) 
1039:                     || (listenerList[i - 1] != null 
1040:                         && listenerList[i - 1].equals(key.getName())) 
1041:                     && ((listenerList[i - 2] == null && key.getType() == null) 
1042:                         || (listenerList[i - 2] != null  
1043:                             && listenerList[i - 2].equals(key.getType()))))) {
1044:                 return true;             
1045:             }
1046:         }
1047:         return false;
1048:     }
1049: 
1050:     /**
1051:      * Removes a listener from the list.
1052:      *
1053:      * @param key
1054:      * @param listener
1055:      */
1056:     public void remove(EventKey key, MElementListener listener) {   
1057:         if (key.getName() != null && key.getType() != null) {
1058:             for (int i = listenerList.length - 3; i >= 0; i -= 3) {
1059:                 if (listenerList[i + 2] == listener
1060:                     && key.getName().equals(listenerList[i + 1])
1061: 		    && key.getType().equals(listenerList[i])) {
1062:                     removeElement(i);
1063:                     break;
1064:                 }
1065:             }
1066:         } else if (key.equals(EventKey.EMPTY_KEY)) {
1067:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1068:                 if (listenerList[i] == listener) {
1069:                     removeElement(i - 2);
1070:                 }
1071:             }
1072:         } else if (key.getName() != null) {
1073:             String name = key.getName();
1074:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1075:                 if (listenerList[i] == listener
1076:                     && name.equals(listenerList[i - 1])) {
1077:                     removeElement(i - 2);
1078:                 }
1079:             }
1080:         } else {
1081:             Integer type = key.getType();
1082:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1083:                 if (listenerList[i] == listener
1084:                     && type.equals(listenerList[i - 2])) {
1085:                     removeElement(i - 2);
1086:                 }
1087:             }
1088:         }
1089: 
1090:     }
1091: 
1092:     /**
1093:      * Does the actual removal of an element at the given index in the list.
1094:      *
1095:      * @param index
1096:      */
1097:     private synchronized void removeElement(int index) {
1098:         Object[] tmp = new Object[listenerList.length - 3];
1099:         // Copy the list up to index
1100:         System.arraycopy(listenerList, 0, tmp, 0, index);
1101:         // Copy from two past the index, up to
1102:         // the end of tmp (which is three elements
1103:         // shorter than the old list)
1104:         if (index < tmp.length) {
1105:             System.arraycopy(listenerList,
1106: 			     index + 3,
1107: 			     tmp,
1108: 			     index,
1109: 			     tmp.length - index);
1110:         }
1111:         // set the listener array to the new array or null
1112:         if (tmp.length == 0) {
1113:             listenerList = NULL_ARRAY;
1114:         } else {
1115:             listenerList = tmp;
1116:         }
1117:     }
1118: 
1119:     /**
1120:      * Returns the number of listeners that are interested in the given key and 
1121:      * exist in the given object array.
1122:      * @param list
1123:      * @param key
1124:      * @return the count of listeners.
1125:      */
1126:     private int getListenerCount(Object[] list, EventKey key) {
1127:         int count = 0;
1128:         String name = key.getName();
1129:         Integer type = key.getType();
1130:         if (type.intValue() == 0) {
1131:             for (int i = 0; i < list.length; i += 3) {
1132:                 if (type.equals(list[i])) {
1133:                     count++;
1134:                 }
1135:             }
1136:         } else if (name != null && type != null) {
1137:             for (int i = 0; i < list.length; i += 3) {
1138:                 if (type.equals(list[i]) && name.equals(list[i + 1])) {
1139:                     count++;
1140:                 }
1141:             }
1142:         } else {
1143:             throw new IllegalArgumentException("Illegal eventkey!");
1144:         }
1145:         return count;
1146:     }
1147: 
1148:     /**
1149:     * Returns the total number of listeners of the supplied type 
1150:     * for this listener list.
1151:     * 
1152:     * @return The number of listeners.
1153:     */
1154:     public synchronized int getListenerCount(EventKey key) {
1155:         return getListenerCount(listenerList, key);
1156:     }
1157: 
1158:     /**
1159:      * Returns the total number of listeners for this listener list.
1160:      * 
1161:      * @return The number of listeners.
1162:      */
1163:     public synchronized int getListenerCount() {
1164:         return listenerList.length / 3;
1165:     }
1166: 
1167:     /**
1168:      * @param ll The listenerList to set.
1169:      */
1170:     void setListenerList(Object[] ll) {
1171:         this.listenerList = ll;
1172:     }
1173: 
1174:     /**
1175:      * @return Returns the listenerList.
1176:      */
1177:     Object[] getListenerList() {
1178:         return listenerList;
1179:     }
1180: 
1181: }
