355:     private synchronized void executeRemoveClassModelEventListener(
356: 	    MElementListener listener,
357: 	    Class modelClass,
358: 	    String eventName) {
359:         // remove all registrations of this listener with all instances of 
360:         // modelClass       
361:         //modelClass = formatClass(modelClass);
362:         Iterator it =
363:             ModelManagementHelper.getHelper()
364: 	        .getAllModelElementsOfKind(modelClass)
365: 	            .iterator();
366:         while (it.hasNext()) {
367:             MBase base = (MBase) it.next();
368:             removeModelEventListener(listener, base, eventName);
369:         }
370:         // remove the listener from the registry
371:         EventKey[] keys = definition.getEventTypes(modelClass, eventName);
372:         for (int i = 0; i < keys.length; i++) {
373:             classListenerMap.remove(modelClass, keys[i], listener);
374:         }
375:     }
