1392:             returnClass =
1393:                 (Class[]) Array.newInstance(Class.class, tmp.length + 1);
1394:             System.arraycopy(tmp, 0, returnClass, 0, tmp.length);
1395:             returnClass[tmp.length] = clazz;
1396:         } else {
1397:             returnClass = new Class[] {
1398: 		clazz,
1399: 	    };
1400:         }
1401:         return returnClass;
