1050:     /**
1051:      * Removes a listener from the list.
1052:      *
1053:      * @param key
1054:      * @param listener
1055:      */
1056:     public void remove(EventKey key, MElementListener listener) {   
1057:         if (key.getName() != null && key.getType() != null) {
1058:             for (int i = listenerList.length - 3; i >= 0; i -= 3) {
1059:                 if (listenerList[i + 2] == listener
1060:                     && key.getName().equals(listenerList[i + 1])
1061: 		    && key.getType().equals(listenerList[i])) {
1062:                     removeElement(i);
1063:                     break;
1064:                 }
1065:             }
1066:         } else if (key.equals(EventKey.EMPTY_KEY)) {
1067:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1068:                 if (listenerList[i] == listener) {
1069:                     removeElement(i - 2);
1070:                 }
1071:             }
1072:         } else if (key.getName() != null) {
1073:             String name = key.getName();
1074:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1075:                 if (listenerList[i] == listener
1076:                     && name.equals(listenerList[i - 1])) {
1077:                     removeElement(i - 2);
1078:                 }
1079:             }
1080:         } else {
1081:             Integer type = key.getType();
1082:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1083:                 if (listenerList[i] == listener
1084:                     && type.equals(listenerList[i - 2])) {
1085:                     removeElement(i - 2);
1086:                 }
1087:             }
1088:         }
1089: 
1090:     }
