1183: /**
1184:  * A map containing instances of meta-classes (modelelements) as keys and 
1185:  * EventListenerLists as values. The class is a wrapper around an underlying
1186:  * java.util.HashMap and provides some custom methods for easy access to the 
1187:  * underlying data structure.
1188:  *
1189:  * @author jaap.branderhorst@xs4all.nl
1190:  */
1191: class EventListenerHashMap {
1192: 
1193:     /**
1194:      * A null array to be shared by all empty listener lists.
1195:      */
1196:     private static final MElementListener[] NULL_ARRAY =
1197:         new MElementListener[0];
1198: 
1199:     /**
1200:      * The list of ListenerType - Listener pairs. 
1201:      */
1202:     private transient Map listenerMap = new HashMap();
1203: 
1204:     /**
1205:      * Puts the given listener as listener to the given modelelement
1206:      * and given eventKey in the map.
1207:      *
1208:      * @param element
1209:      * @param key
1210:      * @param listener
1211:      */
1212:     public synchronized void put(
1213:         MBase element,
1214:         EventKey key,
1215:         MElementListener listener) {     
1216:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1217:         if (list == null) {
1218:             list = new EventListenerList();
1219:             listenerMap.put(element, list);
1220:         }
1221:         list.add(key, listener);
1222:     }
1223: 
1224:     /**
1225:      * Removes a listener for a given eventkey and a given modelelement.
1226:      * @param element
1227:      * @param key
1228:      * @param listener
1229:      */
1230:     public synchronized void remove(
1231:         MBase element,
1232:         EventKey key,
1233:         MElementListener listener) {    
1234:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1235:         if (list != null) {
1236:             list.remove(key, listener);
1237:         }
1238:     }
1239: 
1240:     /**
1241:      * Removes the complete EventListenerList for the given element.
1242:      *
1243:      * @param element
1244:      */
1245:     public synchronized void remove(MBase element) {
1246:         listenerMap.remove(element);
1247:     }
1248: 
1249:     /**
1250:      * Returns all listeners that are registered for the given modelElement and
1251:      * the given EventKey.
1252:      *
1253:      * @param element
1254:      * @param key
1255:      * @return an array of listerns.
1256:      */
1257:     public MElementListener[] getListeners(MBase element, EventKey key) {
1258:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1259:         if (list == null) {
1260:             return NULL_ARRAY;
1261:         } else {
