1277: /**
1278:  * A map that holds ElementListenerLists with lists of listeners that
1279:  * are interested in each and every event of a certain type of the
1280:  * instances of a certain meta-class.
1281:  *
1282:  * @author jaap.branderhorst@xs4all.nl
1283:  */
1284: class ClassListenerHashMap {
1285: 
1286:     /**
1287:      * A null array to be shared by all empty listener lists.
1288:      */
1289:     private static final MElementListener[] NULL_ARRAY =
1290:         new MElementListener[0];
1291: 
1292:     /**
1293:      * The list of ListenerType - Listener pairs. 
1294:      */
1295:     private transient Map listenerMap = new HashMap();
1296: 
1297:     /**
1298:      * Puts a listener that is interested in a certain event that will be send
1299:      * by instances of the given meta-class.
1300:      *
1301:      * @param element The meta-class the listener is interested in
1302:      * @param key The type/name pair designating the event type
1303:      * @param listener The listener that's interested in the given event type
1304:      */
1305:     public synchronized void put(
1306:         Class element,
1307:         EventKey key,
1308:         MElementListener listener) {
1309:         if (element == null || listener == null) {
1310:             throw new IllegalArgumentException("Modelelement or listener null");
1311:         }
1312:         EventListenerList list = 
1313:             (EventListenerList) listenerMap.get(element.getName());
1314:         if (list == null) {
1315:             list = new EventListenerList();
1316:             listenerMap.put(element.getName(), list);
1317:         }
1318:         list.add(key, listener);
1319:     }
1320: 
1321:     /**
1322:      * Removes a listener as being interested in the given event.
1323:      *
1324:      * @param element
1325:      * @param key
1326:      * @param listener
1327:      */
1328:     public synchronized void remove(
1329:         Class element,
1330:         EventKey key,
1331:         MElementListener listener) {
1332:         if (element == null || listener == null) {
1333:             throw new IllegalArgumentException("Modelelement or listener null");
1334:         }
1335:         EventListenerList list = 
1336:             (EventListenerList) listenerMap.get(element.getName());
1337:         if (list != null) {
1338:             list.remove(key, listener);
1339:         }
1340:     }
1341: 
1342:     /**
1343:      * Removes the list of listeners for the given meta-class.
1344:      * @param element
1345:      */
1346:     public synchronized void remove(Class element) {
1347:         listenerMap.remove(element);
1348:     }
1349: 
1350:     /**
1351:      * Returns all listeners that are interested in the given event.
1352:      * @param element
1353:      * @param key
1354:      * @return an array of listeners.
1355:      */
1356:     public MElementListener[] getListeners(Class element, EventKey key) {
1357:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1358:         if (list == null) {
1359:             return NULL_ARRAY;
1360:         } else {
1361:             return list.getListeners(key);
1362:         }
1363:     }
1364: 
1365:     /** 
1366:      * Returns an EventListenerList with listeners that are interested
1367:      * in certain events of the given meta-class.
1368:      *
1369:      * @param element
1370:      * @return an array of EventListenerLists.
1371:      */
1372:     public EventListenerList[] getListenerList(Class element) {
1373:         // element = formatClass(element);
1374:         Class[] hierarchy = getHierarchy(element);
1375:         EventListenerList[] lists = new EventListenerList[hierarchy.length];
1376:         EventListenerList list = null;
1377:         for (int i = 0; i < lists.length; i++) {
1378:             list = (EventListenerList) listenerMap.get(hierarchy[i].getName());
1379:             if (list == null) {
1380:                 lists[i] = new EventListenerList();
1381:             } else {
1382:                 lists[i] = list;
1383:             }
1384:         }
1385:         return lists;
1386:     }
1387: 
1388:     private Class[] getHierarchy(Class clazz) {
1389:         Class[] returnClass = null;
1390:         if (clazz != Object.class) {
1391:             Class[] tmp = getHierarchy(clazz.getSuperclass());
1392:             returnClass =
1393:                 (Class[]) Array.newInstance(Class.class, tmp.length + 1);
1394:             System.arraycopy(tmp, 0, returnClass, 0, tmp.length);
1395:             returnClass[tmp.length] = clazz;
1396:         } else {
1397:             returnClass = new Class[] {
1398: 		clazz,
1399: 	    };
1400:         }
1401:         return returnClass;
1402:     }
1403: 
1404:     /**
1405:      * Tests if the hashmap is empty.
1406:      *
1407:      * @return true if empty.
1408:      */
1409:     public boolean isEmpty() {
1410:         return listenerMap.isEmpty();
1411:     }
1412: 
1413: }
