40: /**
41:  * The checkbox to be used to show boolean attributes in the GUI's. Mostly used
42:  * on proppanels. The other new GUI elements (like UMLLinkedList) divide the 
43:  * responsibility of showing an attribute and maintaining the state of the 
44:  * attribute between a GUI element and a model. This is not the case for the 
45:  * UMLCheckBox2. Reason for this is that the model is just to simple to allow
46:  * extra classes for the model. 
47:  * 
48:  * @since Oct 12, 2002
49:  * @author jaap.branderhorst@xs4all.nl
50:  */
51: public abstract class UMLCheckBox2
52:     extends JCheckBox
53:     implements TargetListener, MElementListener {
54: 
55:     private Object _target;
56:     private String _name;
57:     
58:     /**
59:      * Constructor for UMLCheckBox2.
60:      * @param text
61:      */
62:     public UMLCheckBox2(String text, Action a, String propertySetName) {
63:         super(text);
64:         setFont(LookAndFeelMgr.getInstance().getSmallFont());
65:         _name = propertySetName;
66:         addActionListener(a);
67: 
68: 	// TODO: When no longer requiring support for JDK1.2 this constant
69: 	// can be changed to Action.ACTION_COMMAND_KEY.
70: 	final String ACTION_COMMAND_KEY = "ActionCommandKey";
71:         setActionCommand((String) a.getValue(ACTION_COMMAND_KEY));
72:     }
73: 
74:     /**
75:      * @see ru.novosoft.uml.MElementListener#propertySet(
76:      *          ru.novosoft.uml.MElementEvent)
77:      */
78:     public void propertySet(MElementEvent e) {
79:         if (e.getName().equals(_name))
80:             buildModel();
81:     }
82: 
83:     /**
84:      * @see ru.novosoft.uml.MElementListener#roleAdded(
85:      *          ru.novosoft.uml.MElementEvent)
86:      */
87:     public void roleAdded(MElementEvent e) {
88:     }
89: 
90:     /**
91:      * @see ru.novosoft.uml.MElementListener#roleRemoved(
92:      *          ru.novosoft.uml.MElementEvent)
93:      */
94:     public void roleRemoved(MElementEvent e) {
95:     }
96: 
97:     /**
98:      * @see ru.novosoft.uml.MElementListener#listRoleItemSet(
99:      *          ru.novosoft.uml.MElementEvent)
100:      */
101:     public void listRoleItemSet(MElementEvent e) {
102:     }
103: 
104:     /**
105:      * @see ru.novosoft.uml.MElementListener#removed(
106:      *          ru.novosoft.uml.MElementEvent)
107:      */
108:     public void removed(MElementEvent e) {
109:     }
110: 
111:     /**
112:      * @see ru.novosoft.uml.MElementListener#recovered(
113:      *          ru.novosoft.uml.MElementEvent)
114:      */
115:     public void recovered(MElementEvent e) {
116:     }
117: 
118:     /**
119:      * Returns the target. The target is directly asked from the
120:      * _target attribute and not from the _container attribute to make
121:      * the move to a new targeting system as easy as possible.
122:      *
123:      * @return Object
124:      */
125:     public Object getTarget() {
126:         return _target;
127:     }
128: 
129:     /**
130:      * Sets the target. This method will not be used untill the target does
131:      * not come via the container.
132:      * @param target The target to set
133:      */
134:     public void setTarget(Object target) {
135:         target = target instanceof Fig ? ((Fig) target).getOwner() : target;
136:         if (ModelFacade.isABase(_target)) {
137:             UmlModelEventPump.getPump()
138: 		.removeModelEventListener(this, _target, _name);
139:         }
140:        
141:         if (ModelFacade.isABase(target)) {
142:             _target = target;
143: 	    // UmlModelEventPump.getPump()
144: 	    // .removeModelEventListener(this, (MBase)_target,
145: 	    // _propertySetName);
146: 	    UmlModelEventPump.getPump()
147: 		.addModelEventListener(this, _target, _name);
148:             buildModel();
149:         }
150:             
151:     }
152:     
153:     /**
154:      * Builds the model. That is: it sets the checkbox to true or
155:      * false. The name of this method is choosen to be compliant with
156:      * for example UMLModelElementListModel2.
157:      */
158:     public abstract void buildModel();
159:        
160: 
161:     /**
162:      * TODO: Is this used? I cannot find the reference to
163:      * org.argouml.uml.ui.TargetChangedListener#targetChanged(Object)
164:      */
165:     public void targetChanged(Object newTarget) {
166:         if (_target != newTarget)
167:             setTarget(newTarget);
168:     }
169: 
170:     /**
171:      * TODO: Is this used? I cannot find the reference to
172:      * org.argouml.uml.ui.TargetChangedListener#targetReasserted(Object)
173:      */
174:     public void targetReasserted(Object newTarget) {
175:         if (newTarget != _target)
176:             setTarget(newTarget);
177:     }
178: 
179:     /**
180:      * @see TargetListener#targetAdded(TargetEvent)
181:      */
182:     public void targetAdded(TargetEvent e) {
183:         setTarget(e.getNewTarget());
184:     }
185: 
186:     /**
187:      * @see TargetListener#targetRemoved(TargetEvent)
188:      */
189:     public void targetRemoved(TargetEvent e) {
190:         setTarget(e.getNewTarget());
191:     }
192: 
193:     /**
194:      * @see TargetListener#targetSet(TargetEvent)
195:      */
196:     public void targetSet(TargetEvent e) {
197:         setTarget(e.getNewTarget());
198:     }
199: 
200: }
