1002: class ActionGenerateOne extends UMLAction {
1003:   public ActionGenerateOne() { super("Generate Selected Classes"); }
1004: 
1005:   public void actionPerformed(ActionEvent e) {
1006:     ProjectBrowser pb = ProjectBrowser.TheInstance;
1007:     Editor ce = uci.gef.Globals.curEditor();
1008:     Vector sels = ce.getSelectionManager().getFigs();
1009:     java.util.Enumeration enum = sels.elements();
1010:     Vector classes = new Vector();
1011:     while (enum.hasMoreElements()) {
1012:       Fig f = (Fig) enum.nextElement();
1013:       Object owner = f.getOwner();
1014:       if (!(owner instanceof MMClass) && !(owner instanceof Interface))
1015: 	continue;
