89: /**
90:  * Factory to create UML classes for the UML
91:  * Foundation::Core package. <p>
92:  *
93:  * Feature, StructuralFeature, and PresentationElement do not have a 
94:  * create method since it is called an "abstract metaclass" in the
95:  * UML specifications.
96:  *
97:  * @since ARGO0.11.2
98:  * @author Thierry Lach
99:  * @author Jaap Branderhorst
100:  */
101: public class CoreFactoryImpl
102: 	extends AbstractUmlModelFactory
103: 	implements CoreFactory {
104: 
105:     /**
106:      * Don't allow instantiation.
107:      */
108:     CoreFactoryImpl() {
109:     }
110: 
111:     /**
112:      * Create an empty but initialized instance of a UML Abstraction.
113:      *
114:      * @return an initialized UML Abstraction instance.
115:      */
116:     public Object createAbstraction() {
117: 	Object modelElement =
118: 	    MFactory.getDefaultFactory().createAbstraction();
119: 	super.initialize(modelElement);
120: 	return modelElement;
121:     }
122: 
123:     /**
124:      * Build an empty but initialized instance of a UML Abstraction
125:      * with a given name.
126:      *
127:      * @param name The name.
128:      * @return an initialized UML Abstraction instance.
129:      * @param supplier the supplier of the abstraction
130:      * @param client the client of the abstraction
131:      */
132:     public Object buildAbstraction(String name, Object supplier,
133:             Object client) {
134:         if (!(client instanceof MClassifier)
135:                 || !(supplier instanceof MClassifier)) {
136:             throw new IllegalArgumentException(
137:                 "The supplier and client of an abstraction"
138:                 + "should be classifiers");
139:         }
140:         MAbstraction abstraction = (MAbstraction) createAbstraction();
141:         super.initialize(abstraction);
142:         ModelFacade.setName(abstraction, name);
143:         abstraction.addClient((MClassifier) client);
144:         abstraction.addSupplier((MClassifier) supplier);
145:         return abstraction;
146:     }
147: 
148:     /**
149:      * Create an empty but initialized instance of a UML Association.
150:      *
151:      * @return an initialized UML Association instance.
152:      */
153:     public MAssociation createAssociation() {
154: 	MAssociation modelElement =
155: 	    MFactory.getDefaultFactory().createAssociation();
