1159:     /**
1160:      * Builds a generalization between a parent and a child. Does not check if
1161:      * multiple inheritance is allowed for the current notation.
1162:      *
1163:      * @param child1 is the child
1164:      * @param parent1 is the parent
1165:      * @return MGeneralization
1166:      */
1167:     public MGeneralization buildGeneralization(Object child1, Object parent1) {
1168:         if (!(child1 instanceof MGeneralizableElement)
1169: 	    || !(parent1 instanceof MGeneralizableElement)) {
1170:             throw new IllegalArgumentException();
1171:         }
1172: 
1173:         MGeneralizableElement child = (MGeneralizableElement) child1;
1174:         MGeneralizableElement parent = (MGeneralizableElement) parent1;
1175: 
1176:         if (parent.getParents().contains(child)) {
1177:             return null;
1178:         }
1179:         if (!child.getClass().equals(parent.getClass())) {
1180:             return null;
1181:         }
1182:         Iterator it = parent.getGeneralizations().iterator();
1183:         while (it.hasNext()) {
1184:             MGeneralization gen = (MGeneralization) it.next();
1185:             if (gen.getParent().equals(child)) {
1186:                 return null;
1187:             }
1188:         }
1189:         if (parent.getNamespace() == null) {
1190:             return null;
1191:         }
1192:         if (parent.isLeaf()) {
1193:             return null;
1194:         }
1195:         if (child.isRoot()) {
1196:             return null;
1197:         }
1198: 
1199:         MGeneralization gen = createGeneralization();
1200:         gen.setParent(parent);
1201:         gen.setChild(child);
1202:         if (parent.getNamespace() != null) {
1203:             gen.setNamespace(parent.getNamespace());
1204:         } else if (child.getNamespace() != null) {
1205:             gen.setNamespace(child.getNamespace());
1206:         }
1207:         return gen;
1208:     }
