253:         cat.debug("Removing listener " + listener.toString() + " from modelclass " + modelClass.getName() + ". It was listening to event " + eventName);
254:         Iterator listeners = ModelManagementHelper.getHelper().getAllModelElementsOfKind(modelClass).iterator();
255:         while (listeners.hasNext()) {
256:             MBase base = (MBase) listeners.next();
257:             removeModelEventListener(listener, base, eventName);
258:             cat.debug("Removed the listener " + listener + " that was registred for modelelement " + base + " and event " + eventName);
