74:     public FigFinalState() {
75:         super();
76:         Color handleColor = Globals.getPrefs().getHandleColor();
77:         x = 45;
78:         y = 0;
79:         FigRect bigPort = new FigRect(x, y, width, height);
80:         bigPort.setLineWidth(0);
81:         bigPort.setFilled(false);
