84:         outCircle =
85:             new FigCircle(x, y, width, height, Color.black, Color.white);
86:         inCircle =
87:             new FigCircle(
88:         		  x + 5,
89:         		  y + 5,
90:         		  width - 10,
91:         		  height - 10,
92:         		  handleColor,
93:         		  Color.black);
94:         
95:         outCircle.setLineWidth(1);
96:         inCircle.setLineWidth(0);
97:         
98:         setNameFig(new FigText(x + 10, y + 22, 0, 21, true));
99:         getNameFig().setFilled(false);
100:         getNameFig().setLineWidth(0);
101:         getNameFig().setFont(getLabelFont());
102:         getNameFig().setTextColor(Color.black);
103:         getNameFig().setMultiLine(false);
104:         getNameFig().setAllowsTab(false);
105:         getNameFig().setJustificationByName("center");
106:         	
107:         addFig(bigPort);
108:         addFig(outCircle);
109:         addFig(inCircle);
110:         addFig(getNameFig());
111:         
112:         setBlinkPorts(false); //make port invisble unless mouse enters
113:         Rectangle r = getBounds();
114:     }
