269:     /**
270:      * Makes sure that edges stick to the outer circle and not to the name or
271:      * stereobox.
272:      * @see org.tigris.gef.presentation.Fig#getGravityPoints()
273:      */
274:     public Vector getGravityPoints() {
275:         Vector ret = new Vector();
276:         int cx = outCircle.center().x;
277:         int cy = outCircle.center().y;
278:         int radius = Math.round(outCircle.getWidth() / 2) + 1;
279:         final int maxPoints = 20;
280:         Point point = null;
281:         for (int i = 0; i < maxPoints; i++) {
282:             int x = (int) (cx + Math.cos(2 * Math.PI / maxPoints * i) * radius);
283:             int y = (int) (cy + Math.sin(2 * Math.PI / maxPoints * i) * radius);
284:             point = new Point(x, y);
285:             ret.add(point);
286:         }
287:         return ret;
288:         	
289:     }
