63: public class UMLCollaborationDiagram extends UMLDiagram {
64: 
65:     /** for logging */
66:     private final static Category cat = Category.getInstance("org.argouml.uml.diagram.collaboration.ui.UMLCollaborationDiagram");
67: 
68:     ////////////////
69:     // actions for toolbar
70: 
71:     protected static Action _actionClassifierRole = new CmdCreateNode(MClassifierRole.class, "ClassifierRole");
72: 
73:     protected static Action _actionAssoc = new CmdSetMode(ModeCreatePolyEdge.class, "edgeClass", MAssociationRole.class, "AssociationRole");
74: 
75:     protected static Action _actionGeneralize = new CmdSetMode(ModeCreatePolyEdge.class, "edgeClass", MGeneralization.class, "Generalization");
76: 
77:     protected static Action _actionAssociation = new ActionAddAssociationRole(MAggregationKind.NONE, false, "Association");
78:     protected static Action _actionAggregation = new ActionAddAssociationRole(MAggregationKind.AGGREGATE, false, "Aggregation");
79:     protected static Action _actionComposition = new ActionAddAssociationRole(MAggregationKind.COMPOSITE, false, "Composition");
80:     protected static Action _actionUniAssociation = new ActionAddAssociationRole(MAggregationKind.NONE, true, "UniAssociation");
81:     protected static Action _actionUniAggregation = new ActionAddAssociationRole(MAggregationKind.AGGREGATE, true, "UniAggregation");
82:     protected static Action _actionUniComposition = new ActionAddAssociationRole(MAggregationKind.COMPOSITE, true, "UniComposition");
83: 
84:     ////////////////////////////////////////////////////////////////
85:     // contructors
86:     protected static int _CollaborationDiagramSerial = 1;
87: 
88:     public UMLCollaborationDiagram() {
89: 
90:         try {
91:             setName(getNewDiagramName());
92:         } catch (PropertyVetoException pve) {
93:         }
94:     }
