97:         this();
98:         setNamespace(m);
99:     }
100: 
101:     public int getNumMessages() {
102:         Layer lay = getLayer();
103:         Vector figs = lay.getContents();
104:         int res = 0;
105:         int size = figs.size();
106:         for (int i = 0; i < size; i++) {
107:             Fig f = (Fig) figs.elementAt(i);
108:             if (f.getOwner() instanceof MMessage)
109:                 res++;
110:         }
111:         return res;
112:     }
113: 
114:     /** method to perform a number of important initializations of a <I>CollaborationDiagram</I>. 
115:      * 
116:      * each diagram type has a similar <I>UMLxxxDiagram</I> class.
117:      *
118:      * @param m  MNamespace from the model in NSUML...
119:      * @modified changed <I>lay</I> from <I>LayerPerspective</I> to <I>LayerPerspectiveMutable</I>. 
120:      *           This class is a child of <I>LayerPerspective</I> and was implemented 
121:      *           to correct some difficulties in changing the model. <I>lay</I> is used 
122:      *           mainly in <I>LayerManager</I>(GEF) to control the adding, changing and 
123:      *           deleting layers on the diagram...
124:      *           psager@tigris.org   Jan. 24, 2oo2
125:      */
126:     public void setNamespace(MNamespace m) {
127:         super.setNamespace(m);
128:         CollabDiagramGraphModel gm = new CollabDiagramGraphModel();
129:         gm.setNamespace(m);
130:         setGraphModel(gm);
131:         LayerPerspective lay = new LayerPerspectiveMutable(m.getName(), gm);
132:         setLayer(lay);
133:         CollabDiagramRenderer rend = new CollabDiagramRenderer(); // singleton
134:         lay.setGraphNodeRenderer(rend);
135:         lay.setGraphEdgeRenderer(rend);
136:     }
137: 
138:     /**
139:      * <p>Initialize the toolbar with buttons required for a use case diagram.</p>
140:      * @param toolBar The toolbar to which to add the buttons.
141:      */
142:     protected void initToolBar(JToolBar toolBar) {
143:         toolBar.add(_actionClassifierRole);
144:         toolBar.addSeparator();
145:         toolBar.add(buildAssociationPopup());
146:         //toolBar.add(_actionAssoc);
147:         toolBar.add(ActionAddMessage.SINGLETON);
148:         toolBar.add(_actionGeneralize);
149:     }
150:     
151:     private PopupToolBoxButton buildAssociationPopup() {
152:         PopupToolBoxButton toolBox = new PopupToolBoxButton(_actionAssociation, 0, 2);
153:         toolBox.add(_actionAssociation);
154:         toolBox.add(_actionUniAssociation);
155:         toolBox.add(_actionAggregation);
156:         toolBox.add(_actionUniAggregation);
157:         toolBox.add(_actionComposition);
158:         toolBox.add(_actionUniComposition);
159:         return toolBox;
160:     }
161:     
162: 
