164:     /**  After loading the diagram it?s necessary to connect
165:       *  every FigMessage to its FigAssociationRole. 
166:       *  This is done by adding the FigMessage 
167:       *  to the PathItems of its FigAssociationRole */
168:     public void postLoad() {
169: 
170:         super.postLoad();
171: 
172:         Collection messages;
173:         Iterator msgIterator;
174:         if (getNamespace() == null) {
175:             cat.error("Collaboration Diagram does not belong to a namespace");
176:             return;
177:         }
178:         Collection ownedElements = getNamespace().getOwnedElements();
179:         Iterator oeIterator = ownedElements.iterator();
180:         Layer lay = getLayer();
181:         while (oeIterator.hasNext()) {
182:             MModelElement me = (MModelElement) oeIterator.next();
183:             if (me instanceof MAssociationRole) {
