1660:   protected Object findOrCreate(TXElement e, java.lang.Class cls) {
1661:     String id = e.getAttribute("XMI.id");
1662:     if (id == null) {
1663:       System.out.println("null XMI.id: "+ cls);
1664:     }
1665:     Object obj = null;
1666:     if (id != null && !id.equals("")) obj = _seen.get(id);
1667:     if (obj != null) {
1668:       //if (_dbg) System.out.println("found " + cls + " id=" + id);
1669:       if (obj.getClass() != cls)
1670: 	System.out.println("class mismatch on id=" + id);
1671:       return obj;
1672:     }
1673:     try {
1674:       obj = cls.newInstance();
1675:       int dotPos = id.indexOf(".1");
1676:       if (dotPos > -1) {
1677: 	try {
1678: 	  int idNum = Integer.parseInt(id.substring(dotPos + 2));
1679: 	  _elementIdMax = Math.max(_elementIdMax, idNum);
1680: 	}
1681: 	catch (NumberFormatException ex) { }
1682:       }
1683:       if (obj instanceof ElementImpl)
1684: 	((ElementImpl)obj).setId(id);
1685:       if (id != null && !id.equals("")) _seen.put(id, obj);
1686:       //System.out.println("made " + cls + " id=" + id);
1687:       return obj;
1688:     }
1689:     catch (Exception ex) {
1690:       System.out.println("Exception in createAndHold:" + cls);
1691:       ex.printStackTrace();
1692:     }
1693:     return null;
1694:   }
