551:     if (_firstPass) return;
552:     String s = e.getAttribute("XMI.value");
553:     VisibilityKind k = VisibilityKind.PUBLIC;
554:     if (s == null || s.equals("public")) k = VisibilityKind.PUBLIC;
555:     else if (s.equals("private")) k = VisibilityKind.PRIVATE;
556:     else if (s.equals("protected")) k = VisibilityKind.PROTECTED;
557:     else if (s.equals("package")) k = VisibilityKind.PACKAGE;
558:     //else if (s.equals("unspec")) k = VisibilityKind.UNSPEC;
559:     else System.out.println("unknown VisibilityKind: " + s + ".");
560: 
561:     if (_curME != null) _curME.setVisibility(k);
562:     else System.out.println("can't set Visibility");
563:   }
