25: package org.argouml.uml.ui;
26: import org.argouml.uml.*;
27: import java.util.*;
28: import org.argouml.model.ModelFacade;
29: import org.argouml.model.uml.UmlFactory;
30: 
31: public class UMLComboBoxEntry implements Comparable {
32:     private Object/*MModelElement*/ _element;
33:     private String _shortName;
34:     
35:     /** _longName is composed of an identifier and a name as in Class: String */
36:     private String _longName;
37:     private Profile _profile;
38:     
39:     /** _display name will be the same as shortName unless there 
40:      *  is a name collision */
41:     private String _displayName;
42:     
43:     /** i am not quite sure what _isPhantom means, it may be that it is an
44:      *  entry that is not in the model list...pjs */
45:     private boolean _isPhantom;
46: 
47:     public UMLComboBoxEntry(Object/*MModelElement*/ element, Profile profile, boolean isPhantom) {
48:         _element = element;
49:         if (element != null) {
50:             Object/*MNamespace*/ ns = ModelFacade.getNamespace(element);
51:             _shortName = profile.formatElement(element, ns);
52:         }
53:         else {
54:             _shortName = "";
55:         }
56: 
57: 
58:         //
59:         //   format the element in its own namespace
60:         //       should result in an name without packages
61:         _profile = profile;
62:         _longName = null;
63:         _displayName = _shortName;
64:         _isPhantom = isPhantom;
65:     }
66: 
67:     public String toString() {
68:         return _displayName;
69:     }
70: 
71:     public void updateName() {
72:         if (_element != null) {
73:             Object/*MNamespace*/ ns = ModelFacade.getNamespace(_element);
74:             _shortName = _profile.formatElement(_element, ns);
75:         }
76:     }
77: 
78:     public void checkCollision(String before, String after) {
79:         boolean collision = (before != null && before.equals(_shortName)) ||
80:                 (after != null && after.equals(_shortName));
81:         if (collision) {
82:             if (_longName == null) {
83:                 _longName = getLongName();
84:             }
85:             _displayName = _longName;
86:         }
87:     }
88: 
89:     public String getShortName() {
90:         return _shortName;
91:     }
92: 
93:     public String getLongName() {
94:         if (_longName == null) {
95:             if (_element != null) {
96:                 _longName = _profile.formatElement(_element, null);
97:             }
98:             else {
99:                 _longName = "void";
100:             }
101:         }
102:         return _longName;
103:     }
104: 
105:     // Refactoring: static to denote that it doesn't use any class members.
106:     // TODO:
107:     // Idea to move this to MMUtil together with the same function from
108:     // org/argouml/uml/cognitive/critics/WizOperName.java
109:     // org/argouml/uml/generator/ParserDisplay.java
110:     private static Object findNamespace(Object/*MNamespace*/ phantomNS, Object/*MModel*/ targetModel) {
111:         Object/*MNamespace*/ ns = null;
112:         Object/*MNamespace*/ targetParentNS = null;
113:         Object/*MNamespace*/ parentNS = ModelFacade.getNamespace(phantomNS);
114:         if (parentNS == null) {
115:             ns = targetModel;
116:         }
117:         else {
118:             targetParentNS = findNamespace(parentNS, targetModel);
119:             //
120:             //   see if there is already an element with the same name
121:             //
122:             Collection ownedElements = ModelFacade.getOwnedElements(targetParentNS);
123:             String phantomName = ModelFacade.getName(phantomNS);
124:             String targetName;
125:             if (ownedElements != null) {
126:                 Object/*MModelElement*/ ownedElement;
127:                 Iterator iter = ownedElements.iterator();
128:                 while (iter.hasNext()) {
129:                     ownedElement = iter.next();
130:                     targetName = ModelFacade.getName(ownedElement);
131:                     if (targetName != null && phantomName.equals(targetName)) {
132:                         if (ModelFacade.isAPackage(ownedElement)) {
133:                             ns = ownedElement;
134:                             break;
135:                         }
136:                     }
137:                 }
138:             }
139:             if (ns == null) {
140:                 ns = UmlFactory.getFactory().getModelManagement().createPackage();
141:                 ModelFacade.setName(ns, phantomName);
142:                 ModelFacade.addOwnedElement(targetParentNS, ns);
143:             }
144:         }
145:         return ns;
146:     }
147: 
148:     public Object/*MModelElement*/ getElement(Object targetModel) {
149:         //
150:         //  if phantom then
151:         //    we need to possibly recreate the package structure
152:         //       in the target model
153:         if (_isPhantom && targetModel != null) {
154:             Object/*MNamespace*/ targetNS = findNamespace(ModelFacade.getNamespace(_element), targetModel);
155:             Object/*MModelElement*/ clone = null;
156:             try {
157:                 clone = _element.getClass().getConstructor(new Class[] {}).newInstance(new Object[] {});
158:                 ModelFacade.setName(clone, ModelFacade.getName(_element));
159:                 Object stereo = null;
160:                 if (ModelFacade.getStereotypes(_element).size() > 0) {
161:                     stereo = ModelFacade.getStereotypes(_element).iterator().next();
162:                 }
163:                 ModelFacade.setStereotype(clone, stereo);
164:                 if (ModelFacade.isAStereotype(clone)) {
165:                     ModelFacade.setBaseClass(clone, ModelFacade.getBaseClass(_element));
166:                 }
167:                 ModelFacade.addOwnedElement(targetNS, clone);
168:                 _element = clone;
169:             }
170:             catch (Exception ex) {
171:                 ex.printStackTrace();
172:             }
173:             _isPhantom = false;
174:         }
175:         return _element;
176:     }
177: 
178: 
179:     public void setElement(Object/*MModelElement*/ element, boolean isPhantom) {
180:         _element = element;
181:         _isPhantom = isPhantom;
182:     }
183: 
184:     public int compareTo(final java.lang.Object other) {
185:         int compare = -1;
186:         if (other instanceof UMLComboBoxEntry) {
187:             UMLComboBoxEntry otherEntry = (UMLComboBoxEntry) other;
188:             compare = 0;
189:             if (otherEntry != this) {
190:                 //
191:                 //  if this is a "void" entry it goes first
192:                 //
193:                 if (_element == null) {
194:                     compare = -1;
195:                 }
196:                 else {
197:                     //
198:                     //  if the other one is "void" it goes first
199:                     //
200:                     if (otherEntry.getElement(null) == null) {
201:                         compare = 1;
202:                     }
203:                     else {
204:                         //
205:                         //   compare short names
206:                         //
207:                         compare = getShortName().compareTo(otherEntry.getShortName());
208:                         //
209:                         //   compare long names
210:                         //
211:                         if (compare == 0) {
212:                             compare = getLongName().compareTo(otherEntry.getLongName());
213:                         }
214:                     }
215:                 }
216:             }
217:         }
218:         return compare;
219:     }
220: 
221:     public void nameChanged(Object/*MModelElement*/ element) {
222:         if (element == _element && _element != null) {
223:             Object/*MNamespace*/ ns = ModelFacade.getNamespace(_element);
224:             _shortName = _profile.formatElement(_element, ns);
225:             _displayName = _shortName;
226:             _longName = null;
227:         }
228:     }
229: 
230:     public boolean isPhantom() {
231:         return _isPhantom;
232:     }
233: }

