258: /**
259:  * This is the base class of relays of events.
260:  *
261:  * @author Linus Tolke
262:  */
263: abstract class NSUMLEventListener implements MElementListener {
264:     /**
265:      * Contains a WeakReference.
266:      */
267:     private Reference listenerRef;
268:     private Object element;
269:     private String[] events;
270:     private NSUMLModelEventPump pump;
271: 
272:     /**
273:      * Constructor for the NSUMLEventListener.
274:      *
275:      * @param l The PropertyChangeListener.
276:      * @param e The object we are monitoring, can be a class.
277:      * @param evs The strings that we are interested in.
278:      * @param p The pump that we belong to.
279:      */
280:     NSUMLEventListener(PropertyChangeListener l, Object e, String[] evs,
281:             	       NSUMLModelEventPump p) {
282:         listenerRef = new WeakReference(l);
283:         element = e;
284:         events = evs;
285:         pump = p;
286:     }
287: 
288:     /**
289:      * Returns the listener or <code>null</code> if the listener is
290:      * already Garbage collected.
291:      *
292:      * @return Returns the listener.
293:      */
294:     PropertyChangeListener getListener() {
295:         PropertyChangeListener pcl = (PropertyChangeListener) listenerRef.get();
296:         if (pcl == null) {
297:             delete();
298:         }
299:         return pcl;
300:     }
301: 
302:     /**
303:      * @return Returns the element.
304:      */
305:     Object getElement() {
306:         return element;
307:     }
308:     /**
309:      * @return Returns the events.
310:      */
311:     String[] getEvents() {
312:         return events;
313:     }
314: 
315:     /**
316:      * Unregister this event listener and remove all information about it.
317:      */
318:     public abstract void delete();
319: 
320:     /**
321:      * Returns <code>true</code> if this event listener matches the object
322:      * and event names.
323:      *
324:      * @param e The object to match.
325:      * @param evs The event names to match.
326:      * @return true if matching.
327:      */
328:     public boolean match(Object e, String[] evs) {
329:         if (getElement() != e) {
330:             return false;
331:         }
332:         if (evs == getEvents()) {
333:             return true;
334:         }
335:         if (evs == null) {
336:             return false;
337:         }
338:         if (getEvents() == null) {
339:             return false;
340:         }
341:         if (evs.length != getEvents().length) {
342:             return false;
343:         }
344:         for (int i = 0; i < evs.length; i++) {
345:             int j;
346:             for (j = 0; j < getEvents().length; j++) {
347:                 if (evs[i].equals(getEvents()[j])) {
348:                     break; // Found!
349:                 }
350:             }
351:             if (!(j < getEvents().length)) {
352:                 return false;
353:             }
354:         }
355:         return true;
356:     }
