358:     /**
359:      * Send an event to the listener (if any).
360:      *
361:      * @param pce The event to send.
362:      */
363:     private void fire(PropertyChangeEvent pce) {
364:         pump.fireAction();
365:         PropertyChangeListener pcl = getListener();
366:         if (pcl != null) {
367:             pcl.propertyChange(pce);
368:         }
369:     }
