35: /**
36:  * This layout manager lines up components in 2 columns. All JLabels are the first column and
37:  * any component the JLabel is registered with is in a second column next to the label. <br />
38:  * The height of each row is the largest minimum height of the 2 components. <br />
39:  * The width of the first column is the largest preferred width of the 2 components. <br />
40:  * The width of the 2nd column is any left over space or the maximum width of the component,
41:  * whichever is the least. <br />
42:  * LabelledLayout can show multiple panels of label/component pairs. The seperation of these
43:  * panels is indicated by adding a Seperator component to the parent component. Labelled layout
44:  * starts a new panel when detecting this Seperator.
45:  *
46:  * @author Bob Tarling
47:  */
48: public class LabelledLayout implements LayoutManager, java.io.Serializable {
49: 
50:     /**
51:      * This is the horizontal gap (in pixels) which specifies the space
52:      * between columns.  They can be changed at any time.
53:      * This should be a non negative integer.
54:      *
55:      * @serial
56:      * @see #getHgap()
57:      * @see #setHgap(int)
58:      */
59:     private int _hgap;
60:     
61:     /**
62:      * This is the vertical gap (in pixels) which specifies the space
63:      * between rows.  They can be changed at any time.
64:      * This should be a non negative integer.
65:      *
66:      * @serial
67:      * @see #getVgap()
68:      * @see #setVgap(int)
69:      */
70:     private int _vgap;
71: 
72:     /**
73:      * The height of the child component with the largest height
74:      */
75:     protected int _largestHeight;
76:     /**
77:      * The width of the child component with the largest width
78:      */
79:     protected int _largestWidth;
80:     /**
81:      * The required cell width of the labels column
82:      */
83:     protected int _labelWidth;
84: 
85:     private Orientation _orientation;
86: 
87:     /**
88:      * Construct a new LabelledLayout.
89:      */
90:     public LabelledLayout() {
91:         _orientation = Horizontal.getInstance();
92:         _hgap = 0;
93:         _vgap = 0;
94:     }
95: 
96:     /**
97:      * Construct a new LabelledLayout with the given orientation.
98:      * The orientation determines how panels are layed out. A horizontal orientation
99:      * has panels to the right of the previous. Vertical orientation has panels layed
100:      * out below the previous
101:      */
102:     public LabelledLayout(Orientation orientation) {
103:         _orientation = orientation;
104:         _hgap = 0;
105:         _vgap = 0;
106:     }
107: 
108:     /**
109:      * Construct a new horizontal LabelledLayout with the specified cell spacing.
110:      */
111:     public LabelledLayout(int hgap, int vgap) {
112:         _orientation = Horizontal.getInstance();
113:         _hgap = hgap;
114:         _vgap = vgap;
115:     }
116: 
117:     /** 
118:      * Adds the specified component with the specified name to the layout. This is included
119:      * to satisfy the LayoutManager interface but is not actually used in this layout
120:      * implementation.
121:      *
122:      * @param name the name of the component
123:      * @param comp the component to be added
124:      */
125:     public void addLayoutComponent(String name, Component comp) {
126:     }
127: 
128:     /** 
129:      * Removes the specified component with the specified name from the layout. This is included
130:      * to satisfy the LayoutManager interface but is not actually used in this layout
131:      * implementation.
132:      *
133:      * @param name the name of the component
134:      */
135:     public void removeLayoutComponent(Component comp) {
136:     }
137: 
138:     /**
139:      * Determines the preferred size of the container argument using this labelled layout.
140:      * The preferred size is that all child components are in one section at their own preferred size
141:      * with gaps and border indents.
142:      */
143:     public Dimension preferredLayoutSize(Container parent) {
144:         synchronized (parent.getTreeLock()) {
145:             Insets insets = parent.getInsets();
146:             int preferredWidth = 0;
147:             int preferredHeight = 0;
148:             int widestLabel = 0;
149:             ArrayList rowHeights = new ArrayList();
150: 
151:             int componentCount = parent.getComponentCount();
152:             for (int i = 0; i < componentCount; ++i) {
153:                 Component childComp = parent.getComponent(i);
154:                 if (childComp.isVisible()) {
155:                     int childHeight = (int) childComp.getPreferredSize().getHeight();
156:                     if (childComp instanceof JLabel) {
157:                         JLabel jlabel = (JLabel) childComp;
158:                         if (widestLabel < jlabel.getPreferredSize().getWidth()) {
159:                             widestLabel = (int) jlabel.getPreferredSize().getWidth();
160:                         }
161:                         childComp = jlabel.getLabelFor();
162:                         int childWidth = (int) childComp.getPreferredSize().getWidth();
163:                         if (childWidth > preferredWidth) {
164:                             preferredWidth = childWidth;
165:                         }
166: 
167:                         if (childHeight < jlabel.getPreferredSize().getHeight()) {
168:                             childHeight = (int) jlabel.getPreferredSize().getHeight();
169:                         }
170:                     }
171:                     preferredHeight += childHeight + _vgap;
172:                 }
173:             }
174:             preferredWidth += insets.left + widestLabel + insets.right;
175:             preferredHeight += insets.top + insets.bottom;
176:             return new Dimension(insets.left + widestLabel + preferredWidth + insets.right, preferredHeight);
177:         }
178:     }
179: 
180:     /* Required by LayoutManager. */
181:     public Dimension minimumLayoutSize(Container parent) {
182:         synchronized (parent.getTreeLock()) {
183:             Insets insets = parent.getInsets();
184:             int minimumHeight = insets.top + insets.bottom;
185: 
186:             ArrayList rowHeights = new ArrayList();
187: 
188:             int componentCount = parent.getComponentCount();
189:             for (int i = 0; i < componentCount; ++i) {
190:                 Component childComp = parent.getComponent(i);
191:                 if (childComp instanceof JLabel) {
192:                     JLabel jlabel = (JLabel) childComp;
193:                     childComp = jlabel.getLabelFor();
194:                     int childHeight = (int) childComp.getMinimumSize().getHeight();
195:                     if (childHeight < jlabel.getMinimumSize().getHeight()) {
196:                         childHeight = (int) jlabel.getMinimumSize().getHeight();
197:                     }
198:                     minimumHeight += childHeight + _vgap;
199:                 }
200:             }
201:             return new Dimension(0, minimumHeight);
202:         }
203:     }
204: 
205:     public void layoutContainer(Container parent) {
206:         synchronized (parent.getTreeLock()) {
207:             int sectionX = parent.getInsets().left;
208: 
209:             ArrayList components = new ArrayList();
210:             int sectionCount = getSectionCount(parent);
211:             int sectionWidth = getSectionWidth(parent, sectionCount);
212:             for (int i = 0; i < parent.getComponentCount(); ++i) {
213:                 if (parent.getComponent(i) instanceof Seperator) {
214:                     layoutSection(parent, sectionX, sectionWidth, components);
215:                     sectionX += sectionWidth + _hgap;
216:                     components.clear();
217:                 } else {
218:                     components.add(parent.getComponent(i));
219:                 }
220:             }
221:             layoutSection(parent, sectionX, sectionWidth, components);
222:         }
223:     }
224: 
225:     /** Determine the number of sections.
226:      * There is only ever one section if oriented vertically.
227:      * If oriented horizontally the number of sections is deduced from the number of Splitters
228:      * in the parent container.
229:      */
230:     private int getSectionCount(Container parent) {
231:         int sectionCount = 1;
232:         int componentCount = parent.getComponentCount();
233:         if (_orientation.equals(Horizontal.getInstance())) {
234:             for (int i = 0; i < componentCount; ++i) {
235:                 if (parent.getComponent(i) instanceof Seperator)
236:                     ++sectionCount;
237:             }
238:         }
239:         return sectionCount;
240:     }
241:     
242:     /**
243:      * Determine the width of each section from the section count.
244:      * This is the working width minus the gaps between sections. This result is then divided
245:      * equally by the section count.
246:      */
247:     private int getSectionWidth(Container parent, int sectionCount) {
248:         return (getUsableWidth(parent)-(sectionCount-1)*_hgap) / sectionCount;
249:     }
250: 
251:     /**
252:      * Determine the usable width of the parent.
253:      * This is the full width minus any borders.
254:      */
255:     private int getUsableWidth(Container parent) {
256:         Insets insets = parent.getInsets();
