932: /**
933:  * A wrapped object array that contains triples of eventtype,
934:  * eventname, interested listener. I used an Object array for this
935:  * purpose since it performs fast. Copied a lot of the code from
936:  * javax.swing.EventListenerList.
937:  * @author jaap.branderhorst@xs4all.nl
938:  */
939: class EventListenerList {
940:     /**
941:      * A null array to be shared by all empty listener lists.
942:      */
943:     private static final Object[] NULL_ARRAY = new Object[0];
944:     /**
945:      *  The list of EventKey - Listener pairs. It's visibility is default since
946:      * it's used in AbstractUmlModelFactory in a performant but quite awkward
947:      * way from an encapsulation point of view. 
948:      */
949:     private Object[] listenerList = NULL_ARRAY;
950: 
951:     /**
952:      * Returns an array of listeners that are interested in an event
953:      * that is typed by the given EventKey. If the name is null of the
954:      * EventKey, all listeners are returned that have the
955:      * corresponding name filled or null. Same is true for the type.
956:      *
957:      * @param key
958:      * @return An array of listeners that are interested in the event typed by
959:      * the given EventKey
960:      */
961:     public synchronized MElementListener[] getListeners(EventKey key) {
962:         Object[] lList = listenerList;
963:         int n = getListenerCount(lList, key);
964:         MElementListener[] result =
965:             (MElementListener[]) Array.newInstance(MElementListener.class, n);
966:         int j = 0;
967:         // if the event name is not set we should return all listeners
968:         // interested
969:         if (key.getType().intValue() == 0) {
970:             Integer type = key.getType();
971:             for (int i = lList.length - 3; i >= 0; i -= 3) {
972:                 if (type.equals(lList[i])) {
973:                     result[j++] = (MElementListener) lList[i + 2];
974:                 }
975:             }
976:         } else if (key.getName() != null && key.getType() != null) {
977:             Integer type = key.getType();
978:             String name = key.getName();
979:             for (int i = lList.length - 3; i >= 0; i -= 3) {
980:                 if (name.equals(lList[i + 1]) && type.equals(lList[i])) {
981:                     result[j++] = (MElementListener) lList[i + 2];
982:                 }
983:             }
984:         } else {
985:             throw new IllegalArgumentException("Illegal eventkey!");
986:         }
987:         return result;
988:     }
989: 
990:     /**
991:      * Registers the given listeners for the event typed by
992:      * EventKey. If the name is null (of the EventKey), the listener
993:      * is registred for all events that have a type corresponding to
994:      * the type in the given key, no matter what the name of the event
995:      * is. Vice versa for the type.<p>
996:      *
997:      * <strong>A listener that has been added twice will get the
998:      * events for which it registred twice. Be careful with
999:      * registring listeners!</strong>
1000:      *
1001:      * @param key
1002:      * @param listener
1003:      */
1004:     public synchronized void add(EventKey key, MElementListener listener) {
1005:         if (listener == null || key == null) {
1006:             throw new IllegalArgumentException("Null key or null listener");
1007:         }
1008:         // check if there allready is a listener
1009:         // if (!Arrays.asList(getListeners(key)).contains(listener)) {
1010: 
1011:         if (listenerList == NULL_ARRAY) {
1012:             // if this is the first listener added, 
1013:             // initialize the lists
1014:             listenerList =
1015:                 new Object[] {
1016: 		    key.getType(), key.getName(), listener,
1017: 		};
1018:         } else {
1019:             if (!contains(key, listener)) {
1020:                 // Otherwise copy the array and add the new listener
1021:                 int i = listenerList.length;
1022:                 Object[] tmp = new Object[i + 3];
1023:                 System.arraycopy(listenerList, 0, tmp, 0, i);
1024:                 
1025:                 tmp[i] = key.getType();
1026:                 tmp[i + 1] = key.getName();
1027:                 tmp[i + 2] = listener;            
1028:                 
1029:                 listenerList = tmp;
1030:             }
1031:         }
1032:     }
1033:     
1034:     public boolean contains(EventKey key, MElementListener listener) {       
1035:         if (key == null) {
1036:             System.out.println(" KEy null");
1037:         }
1038:         for (int i = listenerList.length - 1; i > 0; i -= 3) {
1039:             if (listenerList[i] == listener 
1040:                 && ((listenerList[i - 1] == null && key.getName() == null) 
1041:                     || (listenerList[i - 1] != null 
1042:                         && listenerList[i - 1].equals(key.getName())) 
1043:                     && ((listenerList[i - 2] == null && key.getType() == null) 
1044:                         || (listenerList[i - 2] != null  
1045:                             && listenerList[i - 2].equals(key.getType()))))) {
1046:                 return true;             
1047:             }
1048:         }
1049:         return false;
1050:     }
1051: 
1052:     /**
1053:      * Removes a listener from the list.
1054:      *
1055:      * @param key
1056:      * @param listener
1057:      */
1058:     public void remove(EventKey key, MElementListener listener) {   
1059:         if (key.getName() != null && key.getType() != null) {
1060:             for (int i = listenerList.length - 3; i >= 0; i -= 3) {
1061:                 if (listenerList[i + 2] == listener
1062:                     && key.getName().equals(listenerList[i + 1])
1063: 		    && key.getType().equals(listenerList[i])) {
1064:                     removeElement(i);
1065:                     break;
1066:                 }
1067:             }
1068:         } else if (key.equals(EventKey.EMPTY_KEY)) {
1069:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1070:                 if (listenerList[i] == listener) {
1071:                     removeElement(i - 2);
1072:                 }
1073:             }
1074:         } else if (key.getName() != null) {
1075:             String name = key.getName();
1076:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1077:                 if (listenerList[i] == listener
1078:                     && name.equals(listenerList[i - 1])) {
1079:                     removeElement(i - 2);
1080:                 }
1081:             }
1082:         } else {
1083:             Integer type = key.getType();
1084:             for (int i = listenerList.length - 1; i >= 0; i -= 3) {
1085:                 if (listenerList[i] == listener
1086:                     && type.equals(listenerList[i - 2])) {
1087:                     removeElement(i - 2);
1088:                 }
1089:             }
1090:         }
1091: 
1092:     }
1093: 
1094:     /**
1095:      * Does the actual removal of an element at the given index in the list.
1096:      *
1097:      * @param index
1098:      */
1099:     private synchronized void removeElement(int index) {
1100:         Object[] tmp = new Object[listenerList.length - 3];
1101:         // Copy the list up to index
1102:         System.arraycopy(listenerList, 0, tmp, 0, index);
1103:         // Copy from two past the index, up to
1104:         // the end of tmp (which is three elements
1105:         // shorter than the old list)
1106:         if (index < tmp.length) {
1107:             System.arraycopy(listenerList,
1108: 			     index + 3,
1109: 			     tmp,
1110: 			     index,
1111: 			     tmp.length - index);
1112:         }
1113:         // set the listener array to the new array or null
1114:         if (tmp.length == 0) {
1115:             listenerList = NULL_ARRAY;
1116:         } else {
1117:             listenerList = tmp;
1118:         }
1119:     }
