863:         type = t;
864:         setName(n);
865:     }
866: 
867:     /**
868:      * @param t The new type to set.
869:      */
870:     private void setType(int t) {
871:         if (t < 0 || t > 10) {
872:             throw new IllegalArgumentException(
873:                 "This is not a legal eventtype: " + t);
874:         }
875:         type = new Integer(t);
876:     }
