899:     /**
900:      * @see java.lang.Object#hashCode()
901:      */
902:     public int hashCode() {
903:         int code = 0;
904:         if (getType() != null) {
905:             code += getType().hashCode();
906:         }
907:         if (getName() != null) {
908:             code += getName().hashCode();
909:         }
910:         return code;
