916:     public boolean equals(Object o) {
917:         if (o instanceof EventKey) {
918:             EventKey key = (EventKey) o;
919:             if ((key.getType() == null && getType() == null)
920:                 || (key.getType() != null
921: 		    && key.getType().equals(getType())
922: 		    && key.getName() != null
923: 		    && key.getName().equals(getName()))) {
