1212:      * @param listener
1213:      */
1214:     public synchronized void put(
1215:         MBase element,
1216:         EventKey key,
1217:         MElementListener listener) {     
1218:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1219:         if (list == null) {
