808:     public String generateConstraintEnrichedDocComment (MModelElement me) {
809: 	// Retrieve any existing doccomment
810: 	String sDocComment = DocumentationManager.getDocs (me, GeneratorCSharp.INDENT);
811: 
812: 	if (sDocComment != null) {
813: 	    // Fix Bug in documentation manager.defaultFor --> look for current INDENT
814: 	    // and use it
815: 	    for (int i = sDocComment.indexOf ('\n');
816: 		 i >= 0 && i < sDocComment.length();
817: 		 i = sDocComment.indexOf ('\n', i + 1)) {
818: 		sDocComment = sDocComment.substring (0, i + 1) +
819: 		    INDENT + sDocComment.substring (i + 1);
820: 	    }
821: 	}
822: 
823: 	// Extract constraints
824: 	Collection cConstraints = me.getConstraints();
825: 
826: 	if (cConstraints.size() == 0) {
827: 	    return (sDocComment != null) ? (sDocComment) : ("");
828: 	}
829: 
830: 	// Prepare doccomment
831: 	if (sDocComment != null) {
832: 	    // Just remove closing */
833: 	    sDocComment = sDocComment.substring (0, sDocComment.indexOf ("*/") + 1);
834: 	}
835: 	else {
836: 	    if (VERBOSE) {
837: 		sDocComment = INDENT + "/**\n" +
838: 		    INDENT + " * \n" +
839: 		    INDENT + " *";
840: 	    } else {
841: 		sDocComment = "";
842: 	    }
843: 	}
844: 
845: 	// Add each constraint
846: 
847: 	class TagExtractor extends tudresden.ocl.parser.analysis.DepthFirstAdapter {
848: 	    private LinkedList m_llsTags = new LinkedList();
849: 	    private String m_sConstraintName;
850: 	    private int m_nConstraintID = 0;
851: 
852: 	    public TagExtractor (String sConstraintName) {
853: 		super();
854: 
855: 		m_sConstraintName = sConstraintName;
856: 	    }
857: 
858: 	    public Iterator getTags() {
859: 		return m_llsTags.iterator();
860: 	    }
861: 
862: 	    public void caseAConstraintBody (tudresden.ocl.parser.node.AConstraintBody node) {
863: 		// We don't care for anything below this node, so we do not use apply anymore.
864: 		String sKind = (node.getStereotype() != null) ?
865: 		    (node.getStereotype().toString()) :
866: 		    (null);
867: 		String sExpression = (node.getExpression() != null) ?
868: 		    (node.getExpression().toString()) :
869: 		    (null);
870: 		String sName = (node.getName() != null) ?
871: 		    (node.getName().getText()) :
872: 		    (m_sConstraintName + "_" + (m_nConstraintID++));
873: 
874: 		if ((sKind == null) ||
875: 		    (sExpression == null)) {
876: 		    return;
877: 		}
878: 
879: 		String sTag;
880: 		if (sKind.equals ("inv ")) {
881: 		    sTag = "@invariant ";
882: 		}
883: 		else if (sKind.equals ("post ")) {
884: 		    sTag = "@post-condition ";
885: 		}
886: 		else if (sKind.equals ("pre ")) {
887: 		    sTag = "@pre-condition ";
888: 		}
889: 		else {
890: 		    return;
891: 		}
892: 
893: 		sTag += sName + ": " + sExpression;
894: 		m_llsTags.addLast (sTag);
895: 	    }
896: 	}
897: 
898: 	tudresden.ocl.check.types.ModelFacade mf = new org.argouml.ocl.ArgoFacade (me);
899: 	for (Iterator i = cConstraints.iterator(); i.hasNext();) {
900: 	    MConstraint mc = (MConstraint) i.next();
901: 
902: 	    try {
903: 		tudresden.ocl.OclTree otParsed =
904: 		    tudresden.ocl.OclTree.createTree(mc.getBody().getBody(),
905: 						     mf);
906: 
907: 		TagExtractor te = new TagExtractor (mc.getName());
908: 		otParsed.apply (te);
909: 
910: 		for (Iterator j = te.getTags(); j.hasNext();) {
911: 		    sDocComment += " " + j.next() + "\n" + INDENT + " *";
912: 		}
913: 	    }
914: 	    catch (java.io.IOException ioe) {
915: 		// Nothing to be done, should not happen anyway ;-)
916: 	    }
917: 	}
918: 
919: 	sDocComment += "/";
920: 
921: 	return sDocComment;
922:     }
