110:     /** Generates a file for the classifier.
111:      * This method could have been static if it where not for the need to
112:      * call it through the Generatorinterface.
113:      * @return the full path name of the the generated file.
114:      */
115:     public String GenerateFile(Object o, String path) {
116: 	MClassifier cls = (MClassifier) o;
117: 	sect = new Section();
118: 
119: 	String name = cls.getName();
120: 	if (name == null || name.length() == 0) return null;
121: 	String filename = name + ".cs";
122: 	if (!path.endsWith(FILE_SEPARATOR)) path += FILE_SEPARATOR;
123: 
124: 	String packagePath = cls.getNamespace().getName();
125: 	MNamespace parent = cls.getNamespace().getNamespace();
126: 	while (parent != null) {
127: 	    // ommit root package name; it's the model's root
128: 	    if (parent.getNamespace() != null)
129: 		packagePath = parent.getName() + "." + packagePath;
130: 	    parent = parent.getNamespace();
131: 	}
132: 
133: 	int lastIndex = -1;
134: 	do {
135: 	    File f = new File(path);
136: 	    if (!f.isDirectory()) {
137: 		if (!f.mkdir()) {
138: 		    System.out.println(" could not make directory " + path);
139: 		    return null;
140: 		}
141: 	    }
142: 	    if (lastIndex == packagePath.length())
143: 		break;
144: 	    int index = packagePath.indexOf(".", lastIndex + 1);
145: 	    if (index == -1)
146: 		index = packagePath.length();
147: 	    path += packagePath.substring(lastIndex + 1, index) + FILE_SEPARATOR;
148: 	    lastIndex = index;
149: 	} while (true);
150: 	String pathname = path + filename;
151: 	System.out.println("-----" + pathname + "-----");
152: 
153: 	//String pathname = path + filename;
154: 	// TODO: package, project basepath, tagged values to configure
155: 	File f = new File(pathname);
156: 	if (f.exists()) {
157: 	    System.out.println("Generating (updated) " + f.getPath());
158: 	    sect.read(pathname);
159: 	} else {
160: 	    System.out.println("Generating (new) " + f.getPath());
161: 	}
162: 	String header = SINGLETON.generateHeader(cls, pathname, packagePath);
163: 	String src = SINGLETON.generate(cls);
164: 	if (packagePath.length() > 0) src += "\n}";
165: 	BufferedWriter fos = null;
166: 	try {
167: 	    fos = new BufferedWriter(new FileWriter(f));
168: 	    fos.write(header);
169: 	    fos.write(src);
170: 	}
171: 	catch (IOException exp) { }
172: 	finally {
173: 	    try {
174: 		if (fos != null) fos.close();
175: 	    }
176: 	    catch (IOException exp) {
177: 		System.out.println("FAILED: " + f.getPath());
178: 	    }
179: 	}
180: 
181: 	sect.write(pathname, INDENT);
182: 	System.out.println("written: " + pathname);
183: 
184: 
185: 	File f1 = new File(pathname + ".bak");
186: 	if (f1.exists()) {
187: 	    f1.delete();
188: 	}
189: 
190: 	File f2 = new File(pathname);
191: 	if (f2.exists()) {
192: 	    f2.renameTo(new File(pathname + ".bak"));
193: 	}
194: 
195: 	File f3 = new File(pathname + ".out");
196: 	if (f3.exists()) {
197: 	    f3.renameTo(new File(pathname));
198: 	}
199: 
200: 	System.out.println("----- end updating -----");
201: 	return pathname;
202:     }
