353:     public String generateAttribute(Object handle, boolean documented) {
354: 	MAttribute attr = (MAttribute)handle;
355: 	String s = "";
356: 
357: 	String make_get = attr.getTaggedValue("get");
358: 	String make_set = attr.getTaggedValue("set");
359: 
360: 	boolean gen_accessor = false;
361: 
362: 	gen_accessor = (((make_get != null) && (make_get.equals("true"))) ||
363: 			((make_set != null) && (make_set.equals("true"))));
364: 
365: 	/*
366: 	 * Replaced 2001-09-26 STEFFEN ZSCHALER
367: 	 *
368: 	 * Was:
369: 	 *
370: 	 s += DocumentationManager.getDocs(attr) + "\n" + INDENT;
371: 	*/
372: 
373: 	if (documented)
374: 	    s += generateConstraintEnrichedDocComment (attr) + "\n" + INDENT;
375: 	if (gen_accessor)
376: 	    s += " private ";
377: 	else
378: 	    s += generateVisibility(attr);
379: 
380: 	s += generateScope(attr);
381: 	s += generateChangability(attr);
382: 	if (!MMultiplicity.M1_1.equals(attr.getMultiplicity())) {
383: 	    String temp = generateMultiplicity(attr.getMultiplicity());
384: 	    if (temp.length() > 0) {
385: 		s += temp + " ";
386: 	    }
387: 	}
388: 
389: 	MClassifier type = attr.getType();
390: 	if (type != null) {
391: 	    s += generateClassifierRef(type) + " ";
392: 	}
393: 
394: 	String slash = "";
395: 	//    if (attr.containsStereotype(MStereotype.DERIVED)) slash = "/";
396: 	String attr_name = attr.getName();
397: 	MVisibilityKind vis = attr.getVisibility();
398: 
399: 	if (MVisibilityKind.PUBLIC.equals(vis)) {
400: 	    // use original attribute name, no change
401: 	}
402: 	if (MVisibilityKind.PRIVATE.equals(vis)) {
403: 	    attr_name = attr.getOwner().getName() + "_" + attr_name;
404: 
405: 	}
406: 	if (MVisibilityKind.PROTECTED.equals(vis)) {
407: 	    // use orignial name for the moment
408: 	}
409: 
410: 	if (gen_accessor) attr_name = "m_" + attr_name;
411: 
412: 	s += slash + generateName(attr_name);
413: 	MExpression init = attr.getInitialValue();
414: 	if (init != null) {
415: 	    String initStr = generateExpression(init).trim();
416: 	    if (initStr.length() > 0)
417: 		s += " = " + initStr;
418: 	}
419: 
420: 	s += ";\n";
421: 	// s += generateConstraints(attr);  Removed 2001-09-26 STEFFEN ZSCHALER
422: 
423: 	// look if get and set methods are needed (Marian Heddesheimer)
424: 
425: 	//  if get and set are set, visibility is set to same as orig attribute
426: 	//  and a variable with m_ prefix is created.
427: 
428: 
429: 	if ( gen_accessor ) {
430: 
431: 	    s += "\n";
432: 
433: 	    s += INDENT + generateVisibility(attr) + " " + generateClassifierRef(type) + " " + attr.getName() + " {\n";
434: 
435: 	    if ( (make_set != null) && (make_set.equals("true")) )
436: 		s += INDENT + INDENT + "set { m_" + attr.getName() + " = value; } \n";
437: 
438: 	    if ( (make_get != null) && (make_get.equals("true")) )
439: 		s += INDENT + INDENT + "get { return m_" + attr.getName() + "; } \n";
440: 
441: 	    s += INDENT + "}\n";
442: 	}
443: 
444: 	return s;
445:     }
