279:     public String generateOperation(Object cls, boolean documented) {
280: 
281: 	MOperation op = (MOperation) cls;
282: 	String s = "";
283: 
284: 	Object cls = op.getOwner();
285: 
286: 	String nameStr = generateName(op.getName());
287: 	String clsName = generateName(op.getOwner().getName());
288: 
289: 	/*
290: 	 * Replaced 2001-09-26 STEFFEN ZSCHALER
291: 	 *
292: 	 * Was
293: 	 *
294: 	 s += DocumentationManager.getDocs(op) + "\n" + INDENT;
295: 	*/
296: 
297: 	if (documented)
298: 	    s += generateConstraintEnrichedDocComment (op) + "\n" + INDENT;
299: 
300: 	//    s += "function ";
301: 
302: 	if (!(cls instanceof MInterface)) {
303: 	    s += generateAbstractness (op);
304: 	    s += generateScope (op);
305: 	    s += generateChangeability (op);
306: 	    s += generateVisibility (op);
307: 	}
308: 	// pick out return type
309: 	MParameter rp = UmlHelper.getHelper().getCore().getReturnParameter(op);
310: 	if ( rp != null) {
311: 	    MClassifier returnType = rp.getType();
312: 
313: 	    if (returnType == null && !nameStr.equals(clsName)) {
314: 		s += " void ";
315: 	    }
316: 	    else if (returnType != null) {
317: 		s += " " + generateClassifierRef (returnType) + " ";
318: 	    }
319: 	}
320: 	else {
321: 	    //          removed since it was throwing exceptions and didn't seem to do
322: 	    //                 much,  Curt Arnold 15 Jan 2001
323: 	    //
324: 	    //		if (nameStr.equals(clsName)) s += " "; // this is a constructor!
325: 	}
326: 
327: 	// name and params
328: 	Vector params = new Vector (op.getParameters());
329: 	params.remove (rp);
330: 
331: 	s += nameStr + "(";
332: 
333: 	if (params != null) {
334: 	    boolean first = true;
335: 
336: 	    for (int i = 0; i < params.size(); i++) {
337: 		MParameter p = (MParameter) params.elementAt (i);
338: 
339: 		if (!first) s += ", ";
340: 
341: 		s += generateParameter (p);
342: 		first = false;
343: 	    }
344: 	}
345: 
346: 	s += ")";
347: 
348: 	return s;
349: 
350:     }
